import React, { useState, useEffect } from 'react';
import { Area, SessionData, TrainingBlock, DEFAULT_AREAS } from './types';
import { AthleteView } from './components/AthleteView';
import { SetupParameters } from './components/SetupParameters';
import { CoachDashboard } from './components/CoachDashboard';
import { Settings, User, LayoutDashboard } from 'lucide-react';

enum ViewState {
  ATHLETE = 'ATHLETE',
  SETUP = 'SETUP',
  COACH = 'COACH'
}

// Initial 5 empty sessions
const generateEmptyBlock = (): SessionData[] => {
  return Array.from({ length: 5 }, (_, i) => ({
    id: `session-${Date.now()}-${i}`,
    label: `Session ${i + 1}`,
    date: '',
    rpe: 0,
    scores: {},
    notes: '',
    completed: false
  }));
};

const App: React.FC = () => {
  // --- State ---
  const [view, setView] = useState<ViewState>(ViewState.ATHLETE);

  // Persisted Data (In a real app, this goes to Supabase)
  const [areas, setAreas] = useState<Area[]>(() => {
    const saved = localStorage.getItem('flux_areas');
    return saved ? JSON.parse(saved) : DEFAULT_AREAS;
  });

  const [currentSessions, setCurrentSessions] = useState<SessionData[]>(() => {
    const saved = localStorage.getItem('flux_current_block');
    return saved ? JSON.parse(saved) : generateEmptyBlock();
  });

  const [history, setHistory] = useState<TrainingBlock[]>(() => {
    const saved = localStorage.getItem('flux_history');
    return saved ? JSON.parse(saved) : [];
  });

  // --- Effects for Persistence ---
  useEffect(() => {
    localStorage.setItem('flux_areas', JSON.stringify(areas));
  }, [areas]);

  useEffect(() => {
    localStorage.setItem('flux_current_block', JSON.stringify(currentSessions));
  }, [currentSessions]);

  useEffect(() => {
    localStorage.setItem('flux_history', JSON.stringify(history));
  }, [history]);

  // --- Handlers ---

  const handleUpdateAreas = (newAreas: Area[]) => {
    setAreas(newAreas);
    // Note: We do NOT wipe current sessions scores. 
    // Scores are keyed by ID, so if an ID is removed from definitions, it just hides from UI.
  };

  const handleSaveSessions = (updatedSessions: SessionData[]) => {
    setCurrentSessions(updatedSessions);
  };

  const handleSubmitBlock = (finalSessions: SessionData[]) => {
    const newBlock: TrainingBlock = {
        id: `block-${Date.now()}`,
        timestamp: Date.now(),
        submittedAt: new Date().toISOString(),
        areaSnapshot: JSON.parse(JSON.stringify(areas)), // Freeze structure at time of submit
        sessions: finalSessions
    };

    setHistory([...history, newBlock]);
    setCurrentSessions(generateEmptyBlock()); // Reset for next week
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // --- Render ---

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans flex flex-col md:flex-row">

      {/* Mobile Nav (Bottom) */}
      <nav className="md:hidden fixed bottom-0 left-0 w-full bg-slate-900 border-t border-slate-800 z-50 flex justify-around p-3 safe-area-bottom">
        <button 
            onClick={() => setView(ViewState.ATHLETE)}
            className={`flex flex-col items-center gap-1 ${view === ViewState.ATHLETE ? 'text-cyan-400' : 'text-slate-500'}`}
        >
            <User size={20} />
            <span className="text-[10px] font-bold">Training</span>
        </button>
        <button 
            onClick={() => setView(ViewState.COACH)}
            className={`flex flex-col items-center gap-1 ${view === ViewState.COACH ? 'text-cyan-400' : 'text-slate-500'}`}
        >
            <LayoutDashboard size={20} />
            <span className="text-[10px] font-bold">Coach</span>
        </button>
        <button 
            onClick={() => setView(ViewState.SETUP)}
            className={`flex flex-col items-center gap-1 ${view === ViewState.SETUP ? 'text-cyan-400' : 'text-slate-500'}`}
        >
            <Settings size={20} />
            <span className="text-[10px] font-bold">Setup</span>
        </button>
      </nav>

      {/* Desktop Sidebar */}
      <aside className="hidden md:flex flex-col w-64 bg-slate-900 border-r border-slate-800 h-screen sticky top-0 p-6">
         <h1 className="text-2xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-600 mb-8">
             FLUX
         </h1>

         <div className="space-y-2 flex-1">
             <button 
                onClick={() => setView(ViewState.ATHLETE)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${view === ViewState.ATHLETE ? 'bg-cyan-950/50 text-cyan-400 border border-cyan-900' : 'text-slate-400 hover:bg-slate-800'}`}
             >
                 <User size={18} /> <span className="font-bold">Athlete Log</span>
             </button>
             <button 
                onClick={() => setView(ViewState.COACH)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${view === ViewState.COACH ? 'bg-cyan-950/50 text-cyan-400 border border-cyan-900' : 'text-slate-400 hover:bg-slate-800'}`}
             >
                 <LayoutDashboard size={18} /> <span className="font-bold">Coach Dashboard</span>
             </button>
         </div>

         <div className="pt-6 border-t border-slate-800">
             <button 
                onClick={() => setView(ViewState.SETUP)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${view === ViewState.SETUP ? 'bg-slate-800 text-white' : 'text-slate-500 hover:text-white'}`}
             >
                 <Settings size={18} /> <span className="font-medium">Parameters</span>
             </button>
         </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 h-screen overflow-hidden pb-16 md:pb-0 relative">
        {view === ViewState.ATHLETE && (
            <AthleteView 
                areas={areas}
                sessions={currentSessions}
                onSaveSessions={handleSaveSessions}
                onSubmitBlock={handleSubmitBlock}
            />
        )}

        {view === ViewState.SETUP && (
            <SetupParameters 
                areas={areas} 
                onUpdateAreas={handleUpdateAreas}
                onClose={() => setView(ViewState.ATHLETE)}
            />
        )}

        {view === ViewState.COACH && (
            <CoachDashboard 
                currentBlockSessions={currentSessions}
                history={history}
                currentAreas={areas}
            />
        )}
      </main>
    </div>
  );
};

