import React, { useMemo } from 'react';
import { Area, TrainingBlock, SessionData } from '../types';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer,
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend
} from 'recharts';
import { Activity, TrendingUp, CalendarDays } from 'lucide-react';

interface CoachDashboardProps {
  currentBlockSessions: SessionData[];
  history: TrainingBlock[];
  currentAreas: Area[];
}

export const CoachDashboard: React.FC<CoachDashboardProps> = ({ 
  currentBlockSessions, 
  history,
  currentAreas
}) => {

  // --- 1. Data Prep for Radar Chart (Current Status) ---
  // We need to calculate the Average score for each AREA based on the current 5-session block (or whatever is filled).
  const radarData = useMemo(() => {
    // 1. Flatten all scores from current sessions
    const allScores: Record<string, number[]> = {}; // paramId -> [score1, score2...]

    currentBlockSessions.forEach(session => {
        Object.entries(session.scores).forEach(([pId, val]) => {
            if (!allScores[pId]) allScores[pId] = [];
            allScores[pId].push(val as number);
        });
    });

    // 2. Aggregate by Area
    return currentAreas.map(area => {
        let totalScore = 0;
        let count = 0;

        area.parameters.forEach(p => {
            const scores = allScores[p.id] || [];
            if (scores.length > 0) {
                totalScore += scores.reduce((a, b) => a + b, 0);
                count += scores.length;
            }
        });

        return {
            subject: area.name,
            A: count > 0 ? parseFloat((totalScore / count).toFixed(1)) : 0,
            fullMark: 10,
        };
    });
  }, [currentBlockSessions, currentAreas]);

  // --- 2. Data Prep for Line Chart (History) ---
  // Trend of Area Averages over time (historical blocks + current unsubmitted)
  const trendData = useMemo(() => {
    const dataPoints: any[] = [];

    // Helper to process a block
    const processBlock = (blockLabel: string, sessions: SessionData[], areasSnapshot: Area[]) => {
        const point: any = { name: blockLabel };

        areasSnapshot.forEach(area => {
            let areaSum = 0;
            let areaCount = 0;

            // Find scores for parameters belonging to this area ID
            // Note: If areas are renamed/changed significantly, ID matching is key.
            // For simplicity in this "Dynamic" prompt, we match by ID.

            const paramIds = new Set(area.parameters.map(p => p.id));

            sessions.forEach(s => {
                Object.entries(s.scores).forEach(([pId, val]) => {
                    if (paramIds.has(pId)) {
                        areaSum += val as number;
                        areaCount++;
                    }
                });
            });

            point[area.name] = areaCount > 0 ? parseFloat((areaSum / areaCount).toFixed(1)) : 0;
        });

        // Only add point if there's data
        if (Object.keys(point).length > 1) {
             dataPoints.push(point);
        }
    };

    // Process History
    history.forEach((block, idx) => {
        processBlock(`Block ${idx + 1}`, block.sessions, block.areaSnapshot);
    });

    // Process Current (Projected)
    const hasCurrentData = currentBlockSessions.some(s => Object.keys(s.scores).length > 0);
    if (hasCurrentData) {
        processBlock('Current', currentBlockSessions, currentAreas);
    }

    return dataPoints;
  }, [history, currentBlockSessions, currentAreas]);

  // --- Colors for Line Chart Lines ---
  const lineColors = ['#22d3ee', '#818cf8', '#34d399', '#f472b6', '#fbbf24', '#a78bfa'];

  return (
    <div className="flex flex-col h-full bg-slate-950 overflow-y-auto p-4 sm:p-6 space-y-6">

      <div className="mb-4">
        <h2 className="text-2xl font-bold text-white flex items-center gap-3">
          <Activity className="text-cyan-400" /> 
          Performance Dashboard
        </h2>
        <p className="text-slate-400">Real-time analysis of dynamic parameters.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* RADAR CHART */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg">
            <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                <Radar size={20} className="text-cyan-500" /> Current Profile (Average)
            </h3>
            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarData}>
                        <PolarGrid stroke="#334155" />
                        <PolarAngleAxis dataKey="subject" tick={{ fill: '#94a3b8', fontSize: 12 }} />
                        <PolarRadiusAxis angle={30} domain={[0, 10]} tick={{ fill: '#475569', fontSize: 10 }} axisLine={false} />
                        <Radar
                            name="Athlete"
                            dataKey="A"
                            stroke="#06b6d4"
                            strokeWidth={2}
                            fill="#06b6d4"
                            fillOpacity={0.4}
                        />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', color: '#f8fafc' }}
                            itemStyle={{ color: '#22d3ee' }}
                        />
                    </RadarChart>
                </ResponsiveContainer>
            </div>
            <p className="text-xs text-slate-500 text-center mt-2">
                Shows average score per defined Area for the current training block.
            </p>
        </div>

        {/* STATS SUMMARY */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg flex flex-col justify-center">
             <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                <CalendarDays size={20} className="text-blue-500" /> Quick Stats
            </h3>
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-950 p-4 rounded-lg border border-slate-800">
                    <span className="text-slate-500 text-xs uppercase font-bold">Total Sessions</span>
                    <div className="text-3xl font-mono text-white mt-1">
                        {history.reduce((acc, b) => acc + b.sessions.length, 0) + currentBlockSessions.filter(s => s.rpe > 0).length}
                    </div>
                </div>
                <div className="bg-slate-950 p-4 rounded-lg border border-slate-800">
                    <span className="text-slate-500 text-xs uppercase font-bold">Avg RPE (All Time)</span>
                    <div className="text-3xl font-mono text-white mt-1">
                        {(() => {
                            let totalRpe = 0;
                            let count = 0;
                            history.forEach(b => b.sessions.forEach(s => { if(s.rpe>0) { totalRpe+=s.rpe; count++; }}));
                            currentBlockSessions.forEach(s => { if(s.rpe>0) { totalRpe+=s.rpe; count++; }});
                            return count ? (totalRpe/count).toFixed(1) : '-';
                        })()}
                    </div>
                </div>
                <div className="bg-slate-950 p-4 rounded-lg border border-slate-800 col-span-2">
                    <span className="text-slate-500 text-xs uppercase font-bold">Active Parameters</span>
                    <div className="text-xl text-slate-300 mt-1 flex flex-wrap gap-2">
                        {currentAreas.map(a => (
                            <span key={a.id} className="bg-cyan-900/30 text-cyan-400 px-2 py-1 rounded text-xs border border-cyan-900/50">
                                {a.name}: {a.parameters.length}
                            </span>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* LINE CHART */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg lg:col-span-2">
            <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                <TrendingUp size={20} className="text-purple-500" /> Area Progression History
            </h3>
            <div className="h-[350px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={trendData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                        <XAxis dataKey="name" stroke="#94a3b8" />
                        <YAxis domain={[0, 10]} stroke="#94a3b8" />
                        <Tooltip 
                             contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', color: '#f8fafc' }}
                        />
                        <Legend wrapperStyle={{ paddingTop: '10px' }}/>
                        {/* Dynamically generate lines based on current area names found in trend data keys */}
                        {trendData.length > 0 && Object.keys(trendData[0]).filter(k => k !== 'name').map((areaName, idx) => (
                            <Line 
                                key={areaName}
                                type="monotone" 
                                dataKey={areaName} 
                                stroke={lineColors[idx % lineColors.length]} 
                                strokeWidth={3}
                                dot={{ fill: '#0f172a', strokeWidth: 2, r: 4 }}
                                activeDot={{ r: 6 }}
                            />
                        ))}
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </div>

      </div>
      <div className="h-12"></div>
    </div>
  );
};

