import React, { useState, useEffect } from 'react';
import { Area, SessionData } from '../types';
import { Button } from './Button';
import { Save, Send, AlertCircle, Calendar } from 'lucide-react';

interface AthleteViewProps {
  areas: Area[];
  sessions: SessionData[];
  onSaveSessions: (sessions: SessionData[]) => void;
  onSubmitBlock: (sessions: SessionData[]) => void;
}

export const AthleteView: React.FC<AthleteViewProps> = ({ 
  areas, 
  sessions, 
  onSaveSessions, 
  onSubmitBlock 
}) => {
  const [activeSessionId, setActiveSessionId] = useState<string>(sessions[0].id);
  const [localSessions, setLocalSessions] = useState<SessionData[]>(sessions);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  // Sync local state when props change (external updates)
  useEffect(() => {
    setLocalSessions(sessions);
  }, [sessions]);

  const activeSession = localSessions.find(s => s.id === activeSessionId) || localSessions[0];

  const updateSession = (updater: (s: SessionData) => SessionData) => {
    const updated = localSessions.map(s => 
      s.id === activeSessionId ? updater(s) : s
    );
    setLocalSessions(updated);
  };

  const handleScoreChange = (paramId: string, value: number) => {
    updateSession(s => ({
      ...s,
      scores: { ...s.scores, [paramId]: value }
    }));
  };

  const handleRpeChange = (value: number) => {
    updateSession(s => ({ ...s, rpe: value }));
  };

  const handleNotesChange = (text: string) => {
    updateSession(s => ({ ...s, notes: text }));
  };

  const handleManualSave = () => {
    onSaveSessions(localSessions);
    setLastSaved(new Date());
  };

  const handleSubmit = () => {
    if (confirm("Sei sicuro di voler inviare questo blocco di 5 sessioni? I dati verranno archiviati.")) {
        onSubmitBlock(localSessions);
    }
  };

  // Logic for Performance Color (Red -> Green)
  const getPerformanceColorClass = (val: number) => {
    if (val <= 3) return 'bg-red-500 shadow-red-500/50';
    if (val <= 5) return 'bg-orange-500 shadow-orange-500/50';
    if (val <= 7) return 'bg-yellow-400 shadow-yellow-400/50';
    if (val <= 8) return 'bg-lime-400 shadow-lime-400/50';
    return 'bg-emerald-500 shadow-emerald-500/50';
  };

  // Logic for RPE text color (Intensity)
  const getRpeColor = (val: number) => {
    if (val < 4) return 'text-cyan-400';
    if (val < 7) return 'text-yellow-400';
    if (val < 9) return 'text-orange-400';
    return 'text-red-500';
  };

  return (
    <div className="flex flex-col h-full bg-slate-950">
      {/* Header / Nav */}
      <div className="bg-slate-900 border-b border-slate-800 p-4 sticky top-0 z-20">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
            <div>
                 <h2 className="text-xl font-bold text-white tracking-tight">Diario Allenamento</h2>
                 <p className="text-xs text-slate-500">
                     {lastSaved ? `Ultimo salvataggio: ${lastSaved.toLocaleTimeString()}` : 'Modifiche non salvate'}
                 </p>
            </div>
            <div className="flex gap-2">
                <Button variant="secondary" size="sm" onClick={handleManualSave} className="gap-2">
                    <Save size={16} /> Salva Bozza
                </Button>
                <Button variant="primary" size="sm" onClick={handleSubmit} className="gap-2">
                    <Send size={16} /> Invia Blocco
                </Button>
            </div>
        </div>

        {/* Session Tabs */}
        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
            {localSessions.map((s, idx) => (
                <button
                    key={s.id}
                    onClick={() => setActiveSessionId(s.id)}
                    className={`flex flex-col items-center min-w-[4rem] p-2 rounded-lg border transition-all ${
                        activeSessionId === s.id 
                        ? 'bg-cyan-950/40 border-cyan-500 text-cyan-400' 
                        : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                    }`}
                >
                    <span className="text-xs font-bold uppercase">Sess {idx + 1}</span>
                    <span className="text-[10px] opacity-70 truncate w-full text-center">
                        {s.date ? new Date(s.date).toLocaleDateString('it-IT', {weekday:'short'}) : '-'}
                    </span>
                </button>
            ))}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 max-w-3xl mx-auto w-full space-y-8">

        {/* Date Selector */}
        <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800">
            <label className="text-slate-400 text-xs font-bold uppercase mb-2 block flex items-center gap-2">
                <Calendar size={14} /> Data Sessione
            </label>
            <input 
                type="date" 
                value={activeSession.date}
                onChange={(e) => updateSession(s => ({ ...s, date: e.target.value }))}
                className="bg-slate-950 border border-slate-700 rounded-lg px-4 py-2 text-white w-full sm:w-auto focus:border-cyan-500 outline-none"
            />
        </div>

        {/* RPE Scale */}
        <div className="bg-slate-900 rounded-xl border border-slate-800 p-6 shadow-lg relative overflow-hidden">
            <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-cyan-500 to-blue-600"></div>
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white">Scala RPE (Sforzo Percepito)</h3>
                <span className={`text-2xl font-black ${getRpeColor(activeSession.rpe)}`}>
                    {activeSession.rpe} <span className="text-sm text-slate-500 font-normal">/ 11</span>
                </span>
            </div>

            <input
                type="range"
                min="0"
                max="11"
                step="0.5"
                value={activeSession.rpe}
                onChange={(e) => handleRpeChange(parseFloat(e.target.value))}
                className="w-full h-3 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-500 hover:accent-cyan-400 transition-all"
            />
            <div className="flex justify-between text-xs text-slate-500 mt-2 font-mono">
                <span>Riposo</span>
                <span>Moderato</span>
                <span>Massimale</span>
            </div>
        </div>

        {/* Dynamic Parameters */}
        <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-200 flex items-center gap-2">
                Metriche di Valutazione
            </h3>

            {areas.length === 0 && (
                <div className="text-center p-8 border border-dashed border-slate-800 rounded-lg text-slate-500">
                    <AlertCircle className="mx-auto mb-2" />
                    Nessun parametro definito. Vai alle impostazioni.
                </div>
            )}

            {areas.map(area => (
                <div key={area.id} className="bg-slate-900/50 rounded-xl border border-slate-800/60 p-5">
                    <h4 className="text-cyan-400 font-bold mb-4 text-sm uppercase tracking-wider">{area.name}</h4>
                    <div className="space-y-8">
                        {area.parameters.length === 0 && <p className="text-xs text-slate-600 italic">Nessun parametro in quest'area</p>}
                        {area.parameters.map(param => {
                            const score = activeSession.scores[param.id] ?? 5;
                            return (
                                <div key={param.id} className="space-y-3">
                                    <div className="flex justify-between items-center">
                                        <label className="text-slate-300 text-sm font-medium">{param.name}</label>
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-slate-900 text-sm shadow-lg transition-all ${getPerformanceColorClass(score)}`}>
                                            {score}
                                        </div>
                                    </div>

                                    <div className="relative pt-1">
                                        <input
                                            type="range"
                                            min="1"
                                            max="10"
                                            step="1"
                                            value={score}
                                            onChange={(e) => handleScoreChange(param.id, parseInt(e.target.value))}
                                            className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-slate-500 z-10 relative"
                                        />

                                        {/* Visual Color Scale Below */}
                                        <div className="h-1.5 w-full mt-2 rounded-full flex overflow-hidden opacity-80">
                                            <div className="w-[30%] bg-red-500"></div>
                                            <div className="w-[20%] bg-orange-500"></div>
                                            <div className="w-[20%] bg-yellow-400"></div>
                                            <div className="w-[30%] bg-emerald-500"></div>
                                        </div>
                                        <div className="flex justify-between text-[10px] text-slate-500 mt-1 uppercase font-bold tracking-wider">
                                            <span className="text-red-500">Insufficiente</span>
                                            <span className="text-emerald-500">Eccellente</span>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            ))}
        </div>

        {/* Notes */}
        <div className="bg-slate-900 rounded-xl border border-slate-800 p-5">
            <h3 className="text-sm font-bold text-slate-300 mb-3 uppercase">Note Sessione</h3>
            <textarea
                value={activeSession.notes}
                onChange={(e) => handleNotesChange(e.target.value)}
                placeholder="Come ti sei sentito oggi? Progressi tecnici? Stanchezza?"
                className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-slate-200 placeholder-slate-600 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-900 outline-none h-32 transition-colors resize-none"
            />
        </div>

        {/* Footer spacing */}
        <div className="h-12"></div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Area, Parameter } from '../types';
import { Plus, Trash2, Edit2, Check, X } from 'lucide-react';
import { Button } from './Button';

interface SetupParametersProps {
  areas: Area[];
  onUpdateAreas: (newAreas: Area[]) => void;
  onClose: () => void;
}

export const SetupParameters: React.FC<SetupParametersProps> = ({ areas, onUpdateAreas, onClose }) => {
  const [localAreas, setLocalAreas] = useState<Area[]>(JSON.parse(JSON.stringify(areas)));
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  // Handlers for Areas
  const addArea = () => {
    const newArea: Area = {
      id: `area-${Date.now()}`,
      name: 'Nuova Area',
      parameters: [{ id: `p-${Date.now()}`, name: 'Parametro 1' }],
    };
    setLocalAreas([...localAreas, newArea]);
  };

  const removeArea = (id: string) => {
    setLocalAreas(localAreas.filter(a => a.id !== id));
  };

  const updateAreaName = (id: string, name: string) => {
    setLocalAreas(localAreas.map(a => a.id === id ? { ...a, name } : a));
    setEditingId(null);
  };

  // Handlers for Parameters
  const addParameter = (areaId: string) => {
    setLocalAreas(localAreas.map(area => {
      if (area.id !== areaId) return area;
      return {
        ...area,
        parameters: [...area.parameters, { id: `p-${Date.now()}`, name: 'Nuovo Parametro' }]
      };
    }));
  };

  const removeParameter = (areaId: string, paramId: string) => {
    setLocalAreas(localAreas.map(area => {
      if (area.id !== areaId) return area;
      return {
        ...area,
        parameters: area.parameters.filter(p => p.id !== paramId)
      };
    }));
  };

  const updateParameterName = (areaId: string, paramId: string, name: string) => {
    setLocalAreas(localAreas.map(area => {
      if (area.id !== areaId) return area;
      return {
        ...area,
        parameters: area.parameters.map(p => p.id === paramId ? { ...p, name } : p)
      };
    }));
    setEditingId(null);
  };

  // Edit Mode Handler
  const startEditing = (id: string, currentName: string) => {
    setEditingId(id);
    setEditValue(currentName);
  };

  const handleSave = () => {
    onUpdateAreas(localAreas);
    onClose();
  };

  return (
    <div className="flex flex-col h-full bg-slate-950">
      <div className="p-6 border-b border-slate-800 flex justify-between items-center sticky top-0 bg-slate-950/90 backdrop-blur z-10">
        <div>
          <h2 className="text-2xl font-bold text-white">Configurazione Sistema</h2>
          <p className="text-slate-400 text-sm">Personalizza il tuo modello di valutazione.</p>
        </div>
        <div className="flex gap-3">
          <Button variant="ghost" onClick={onClose}>Annulla</Button>
          <Button onClick={handleSave} className="flex items-center gap-2">
            <Check size={18} /> Applica Modifiche
          </Button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 max-w-4xl mx-auto w-full">
        {localAreas.map((area) => (
          <div key={area.id} className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-sm">
            <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-800">
              <div className="flex items-center gap-3 flex-1">
                {editingId === area.id ? (
                  <div className="flex items-center gap-2 w-full max-w-xs">
                    <input
                      autoFocus
                      type="text"
                      value={editValue}
                      onChange={(e) => setEditValue(e.target.value)}
                      className="bg-slate-800 border border-cyan-500/50 rounded px-3 py-1 text-white w-full outline-none"
                    />
                    <button onClick={() => updateAreaName(area.id, editValue)} className="text-cyan-400 hover:text-cyan-300"><Check size={18}/></button>
                  </div>
                ) : (
                  <h3 className="text-xl font-bold text-cyan-400 flex items-center gap-3">
                    {area.name}
                    <button onClick={() => startEditing(area.id, area.name)} className="text-slate-600 hover:text-slate-400"><Edit2 size={16}/></button>
                  </h3>
                )}
              </div>
              <Button variant="danger" size="sm" onClick={() => removeArea(area.id)} title="Rimuovi Area">
                <Trash2 size={16} />
              </Button>
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              {area.parameters.map((param) => (
                <div key={param.id} className="flex items-center justify-between bg-slate-950/50 p-3 rounded border border-slate-800/50 hover:border-slate-700 transition-colors">
                   {editingId === param.id ? (
                     <div className="flex items-center gap-2 w-full">
                       <input
                         autoFocus
                         type="text"
                         value={editValue}
                         onChange={(e) => setEditValue(e.target.value)}
                         className="bg-slate-800 border border-cyan-500/50 rounded px-2 py-1 text-sm text-white w-full outline-none"
                       />
                       <button onClick={() => updateParameterName(area.id, param.id, editValue)} className="text-cyan-400"><Check size={16}/></button>
                     </div>
                   ) : (
                     <div className="flex items-center gap-2 text-slate-300 text-sm">
                        <span className="w-2 h-2 rounded-full bg-slate-700"></span>
                        {param.name}
                        <button onClick={() => startEditing(param.id, param.name)} className="text-slate-600 hover:text-slate-400 ml-2"><Edit2 size={12}/></button>
                     </div>
                   )}
                   <button onClick={() => removeParameter(area.id, param.id)} className="text-slate-600 hover:text-red-400 transition-colors">
                     <X size={16} />
                   </button>
                </div>
              ))}
              <button 
                onClick={() => addParameter(area.id)}
                className="flex items-center justify-center gap-2 p-3 rounded border border-dashed border-slate-700 text-slate-500 hover:text-cyan-400 hover:border-cyan-500/50 transition-all text-sm"
              >
                <Plus size={16} /> Aggiungi Parametro
              </button>
            </div>
          </div>
        ))}

        <button 
          onClick={addArea}
          className="w-full py-8 border-2 border-dashed border-slate-800 rounded-xl text-slate-500 hover:text-cyan-400 hover:border-cyan-500/30 hover:bg-slate-900/50 transition-all flex flex-col items-center gap-2"
        >
          <div className="p-3 bg-slate-900 rounded-full">
            <Plus size={24} />
          </div>
          <span className="font-medium">Aggiungi Area di Valutazione</span>
        </button>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { Area, TrainingBlock, SessionData } from '../types';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer,
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend
} from 'recharts';
import { Activity, TrendingUp, CalendarDays } from 'lucide-react';

interface CoachDashboardProps {
  currentBlockSessions: SessionData[];
  history: TrainingBlock[];
  currentAreas: Area[];
}

export const CoachDashboard: React.FC<CoachDashboardProps> = ({ 
  currentBlockSessions, 
  history,
  currentAreas
}) => {

  // --- 1. Data Prep for Radar Chart (Current Status) ---
  const radarData = useMemo(() => {
    // 1. Flatten all scores from current sessions
    const allScores: Record<string, number[]> = {}; // paramId -> [score1, score2...]

    currentBlockSessions.forEach(session => {
        Object.entries(session.scores).forEach(([pId, val]) => {
            if (!allScores[pId]) allScores[pId] = [];
            allScores[pId].push(val as number);
        });
    });

    // 2. Aggregate by Area
    return currentAreas.map(area => {
        let totalScore = 0;
        let count = 0;

        area.parameters.forEach(p => {
            const scores = allScores[p.id] || [];
            if (scores.length > 0) {
                totalScore += scores.reduce((a, b) => a + b, 0);
                count += scores.length;
            }
        });

        return {
            subject: area.name,
            A: count > 0 ? parseFloat((totalScore / count).toFixed(1)) : 0,
            fullMark: 10,
        };
    });
  }, [currentBlockSessions, currentAreas]);

  // --- 2. Data Prep for Line Chart (History) ---
  const trendData = useMemo(() => {
    const dataPoints: any[] = [];

    // Helper to process a block
    const processBlock = (blockLabel: string, sessions: SessionData[], areasSnapshot: Area[]) => {
        const point: any = { name: blockLabel };

        areasSnapshot.forEach(area => {
            let areaSum = 0;
            let areaCount = 0;

            const paramIds = new Set(area.parameters.map(p => p.id));

            sessions.forEach(s => {
                Object.entries(s.scores).forEach(([pId, val]) => {
                    if (paramIds.has(pId)) {
                        areaSum += val as number;
                        areaCount++;
                    }
                });
            });

            point[area.name] = areaCount > 0 ? parseFloat((areaSum / areaCount).toFixed(1)) : 0;
        });

        // Only add point if there's data
        if (Object.keys(point).length > 1) {
             dataPoints.push(point);
        }
    };

    // Process History
    history.forEach((block, idx) => {
        processBlock(`Blocco ${idx + 1}`, block.sessions, block.areaSnapshot);
    });

    // Process Current (Projected)
    const hasCurrentData = currentBlockSessions.some(s => Object.keys(s.scores).length > 0);
    if (hasCurrentData) {
        processBlock('Attuale', currentBlockSessions, currentAreas);
    }

    return dataPoints;
  }, [history, currentBlockSessions, currentAreas]);

  // --- Colors for Line Chart Lines ---
  const lineColors = ['#22d3ee', '#818cf8', '#34d399', '#f472b6', '#fbbf24', '#a78bfa'];

  return (
    <div className="flex flex-col h-full bg-slate-950 overflow-y-auto p-4 sm:p-6 space-y-6">

      <div className="mb-4">
        <h2 className="text-2xl font-bold text-white flex items-center gap-3">
          <Activity className="text-cyan-400" /> 
          Dashboard Prestazioni
        </h2>
        <p className="text-slate-400">Analisi in tempo reale dei parametri dinamici.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* RADAR CHART */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg">
            <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                <Radar size={20} className="text-cyan-500" /> Profilo Attuale (Media)
            </h3>
            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarData}>
                        <PolarGrid stroke="#334155" />
                        <PolarAngleAxis dataKey="subject" tick={{ fill: '#94a3b8', fontSize: 12 }} />
                        <PolarRadiusAxis angle={30} domain={[0, 10]} tick={{ fill: '#475569', fontSize: 10 }} axisLine={false} />
                        <Radar
                            name="Atleta"
                            dataKey="A"
                            stroke="#06b6d4"
                            strokeWidth={2}
                            fill="#06b6d4"
                            fillOpacity={0.4}
                        />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', color: '#f8fafc' }}
                            itemStyle={{ color: '#22d3ee' }}
                        />
                    </RadarChart>
                </ResponsiveContainer>
            </div>
            <p className="text-xs text-slate-500 text-center mt-2">
                Mostra il punteggio medio per area definita nel blocco corrente.
            </p>
        </div>

        {/* STATS SUMMARY */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg flex flex-col justify-center">
             <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                <CalendarDays size={20} className="text-blue-500" /> Statistiche Veloci
            </h3>
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-950 p-4 rounded-lg border border-slate-800">
                    <span className="text-slate-500 text-xs uppercase font-bold">Sessioni Totali</span>
                    <div className="text-3xl font-mono text-white mt-1">
                        {history.reduce((acc, b) => acc + b.sessions.length, 0) + currentBlockSessions.filter(s => s.rpe > 0).length}
                    </div>
                </div>
                <div className="bg-slate-950 p-4 rounded-lg border border-slate-800">
                    <span className="text-slate-500 text-xs uppercase font-bold">RPE Medio (Totale)</span>
                    <div className="text-3xl font-mono text-white mt-1">
                        {(() => {
                            let totalRpe = 0;
                            let count = 0;
                            history.forEach(b => b.sessions.forEach(s => { if(s.rpe>0) { totalRpe+=s.rpe; count++; }}));
                            currentBlockSessions.forEach(s => { if(s.rpe>0) { totalRpe+=s.rpe; count++; }});
                            return count ? (totalRpe/count).toFixed(1) : '-';
                        })()}
                    </div>
                </div>
                <div className="bg-slate-950 p-4 rounded-lg border border-slate-800 col-span-2">
                    <span className="text-slate-500 text-xs uppercase font-bold">Parametri Attivi</span>
                    <div className="text-xl text-slate-300 mt-1 flex flex-wrap gap-2">
                        {currentAreas.map(a => (
                            <span key={a.id} className="bg-cyan-900/30 text-cyan-400 px-2 py-1 rounded text-xs border border-cyan-900/50">
                                {a.name}: {a.parameters.length}
                            </span>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* LINE CHART */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg lg:col-span-2">
            <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                <TrendingUp size={20} className="text-purple-500" /> Storico Progressi Aree
            </h3>
            <div className="h-[350px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={trendData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                        <XAxis dataKey="name" stroke="#94a3b8" />
                        <YAxis domain={[0, 10]} stroke="#94a3b8" />
                        <Tooltip 
                             contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', color: '#f8fafc' }}
                        />
                        <Legend wrapperStyle={{ paddingTop: '10px' }}/>
                        {/* Dynamically generate lines based on current area names found in trend data keys */}
                        {trendData.length > 0 && Object.keys(trendData[0]).filter(k => k !== 'name').map((areaName, idx) => (
                            <Line 
                                key={areaName}
                                type="monotone" 
                                dataKey={areaName} 
                                stroke={lineColors[idx % lineColors.length]} 
                                strokeWidth={3}
                                dot={{ fill: '#0f172a', strokeWidth: 2, r: 4 }}
                                activeDot={{ r: 6 }}
                            />
                        ))}
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </div>

      </div>
      <div className="h-12"></div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Area, SessionData, TrainingBlock, DEFAULT_AREAS } from './types';
import { AthleteView } from './components/AthleteView';
import { SetupParameters } from './components/SetupParameters';
import { CoachDashboard } from './components/CoachDashboard';
import { Settings, User, LayoutDashboard } from 'lucide-react';

enum ViewState {
  ATHLETE = 'ATHLETE',
  SETUP = 'SETUP',
  COACH = 'COACH'
}

// Initial 5 empty sessions
const generateEmptyBlock = (): SessionData[] => {
  return Array.from({ length: 5 }, (_, i) => ({
    id: `session-${Date.now()}-${i}`,
    label: `Sessione ${i + 1}`,
    date: '',
    rpe: 0,
    scores: {},
    notes: '',
    completed: false
  }));
};

const App: React.FC = () => {
  // --- State ---
  const [view, setView] = useState<ViewState>(ViewState.ATHLETE);

  // Persisted Data (In a real app, this goes to Supabase)
  const [areas, setAreas] = useState<Area[]>(() => {
    const saved = localStorage.getItem('flux_areas');
    return saved ? JSON.parse(saved) : DEFAULT_AREAS;
  });

  const [currentSessions, setCurrentSessions] = useState<SessionData[]>(() => {
    const saved = localStorage.getItem('flux_current_block');
    return saved ? JSON.parse(saved) : generateEmptyBlock();
  });

  const [history, setHistory] = useState<TrainingBlock[]>(() => {
    const saved = localStorage.getItem('flux_history');
    return saved ? JSON.parse(saved) : [];
  });

  // --- Effects for Persistence ---
  useEffect(() => {
    localStorage.setItem('flux_areas', JSON.stringify(areas));
  }, [areas]);

  useEffect(() => {
    localStorage.setItem('flux_current_block', JSON.stringify(currentSessions));
  }, [currentSessions]);

  useEffect(() => {
    localStorage.setItem('flux_history', JSON.stringify(history));
  }, [history]);

  // --- Handlers ---

  const handleUpdateAreas = (newAreas: Area[]) => {
    setAreas(newAreas);
    // Note: We do NOT wipe current sessions scores. 
    // Scores are keyed by ID, so if an ID is removed from definitions, it just hides from UI.
  };

  const handleSaveSessions = (updatedSessions: SessionData[]) => {
    setCurrentSessions(updatedSessions);
  };

  const handleSubmitBlock = (finalSessions: SessionData[]) => {
    const newBlock: TrainingBlock = {
        id: `block-${Date.now()}`,
        submittedAt: new Date().toISOString(),
        areaSnapshot: JSON.parse(JSON.stringify(areas)), // Freeze structure at time of submit
        sessions: finalSessions
    };

    setHistory([...history, newBlock]);
    setCurrentSessions(generateEmptyBlock()); // Reset for next week
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // --- Render ---

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans flex flex-col md:flex-row">

      {/* Mobile Nav (Bottom) */}
      <nav className="md:hidden fixed bottom-0 left-0 w-full bg-slate-900 border-t border-slate-800 z-50 flex justify-around p-3 safe-area-bottom">
        <button 
            onClick={() => setView(ViewState.ATHLETE)}
            className={`flex flex-col items-center gap-1 ${view === ViewState.ATHLETE ? 'text-cyan-400' : 'text-slate-500'}`}
        >
            <User size={20} />
            <span className="text-[10px] font-bold">Allenamento</span>
        </button>
        <button 
            onClick={() => setView(ViewState.COACH)}
            className={`flex flex-col items-center gap-1 ${view === ViewState.COACH ? 'text-cyan-400' : 'text-slate-500'}`}
        >
            <LayoutDashboard size={20} />
            <span className="text-[10px] font-bold">Coach</span>
        </button>
        <button 
            onClick={() => setView(ViewState.SETUP)}
            className={`flex flex-col items-center gap-1 ${view === ViewState.SETUP ? 'text-cyan-400' : 'text-slate-500'}`}
        >
            <Settings size={20} />
            <span className="text-[10px] font-bold">Setup</span>
        </button>
      </nav>

      {/* Desktop Sidebar */}
      <aside className="hidden md:flex flex-col w-64 bg-slate-900 border-r border-slate-800 h-screen sticky top-0 p-6">
         <h1 className="text-2xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-600 mb-8">
             FLUX
         </h1>

         <div className="space-y-2 flex-1">
             <button 
                onClick={() => setView(ViewState.ATHLETE)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${view === ViewState.ATHLETE ? 'bg-cyan-950/50 text-cyan-400 border border-cyan-900' : 'text-slate-400 hover:bg-slate-800'}`}
             >
                 <User size={18} /> <span className="font-bold">Diario Atleta</span>
             </button>
             <button 
                onClick={() => setView(ViewState.COACH)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${view === ViewState.COACH ? 'bg-cyan-950/50 text-cyan-400 border border-cyan-900' : 'text-slate-400 hover:bg-slate-800'}`}
             >
                 <LayoutDashboard size={18} /> <span className="font-bold">Dashboard Coach</span>
             </button>
         </div>

         <div className="pt-6 border-t border-slate-800">
             <button 
                onClick={() => setView(ViewState.SETUP)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${view === ViewState.SETUP ? 'bg-slate-800 text-white' : 'text-slate-500 hover:text-white'}`}
             >
                 <Settings size={18} /> <span className="font-medium">Parametri</span>
             </button>
         </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 h-screen overflow-hidden pb-16 md:pb-0 relative">
        {view === ViewState.ATHLETE && (
            <AthleteView 
                areas={areas}
                sessions={currentSessions}
                onSaveSessions={handleSaveSessions}
                onSubmitBlock={handleSubmitBlock}
            />
        )}

        {view === ViewState.SETUP && (
            <SetupParameters 
                areas={areas} 
                onUpdateAreas={handleUpdateAreas}
                onClose={() => setView(ViewState.ATHLETE)}
            />
        )}

        {view === ViewState.COACH && (
            <CoachDashboard 
                currentBlockSessions={currentSessions}
                history={history}
                currentAreas={areas}
            />
        )}
      </main>
    </div>
  );
};

