import React, { useState, useEffect } from 'react';
import { Area, SessionData } from '../types';
import { Button } from './Button';
import { Save, Send, AlertCircle, Calendar } from 'lucide-react';

interface AthleteViewProps {
  areas: Area[];
  sessions: SessionData[];
  onSaveSessions: (sessions: SessionData[]) => void;
  onSubmitBlock: (sessions: SessionData[]) => void;
}

export const AthleteView: React.FC<AthleteViewProps> = ({ 
  areas, 
  sessions, 
  onSaveSessions, 
  onSubmitBlock 
}) => {
  const [activeSessionId, setActiveSessionId] = useState<string>(sessions[0].id);
  const [localSessions, setLocalSessions] = useState<SessionData[]>(sessions);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  // Sync local state when props change (external updates)
  useEffect(() => {
    setLocalSessions(sessions);
  }, [sessions]);

  const activeSession = localSessions.find(s => s.id === activeSessionId) || localSessions[0];

  const updateSession = (updater: (s: SessionData) => SessionData) => {
    const updated = localSessions.map(s => 
      s.id === activeSessionId ? updater(s) : s
    );
    setLocalSessions(updated);
  };

  const handleScoreChange = (paramId: string, value: number) => {
    updateSession(s => ({
      ...s,
      scores: { ...s.scores, [paramId]: value }
    }));
  };

  const handleRpeChange = (value: number) => {
    updateSession(s => ({ ...s, rpe: value }));
  };

  const handleNotesChange = (text: string) => {
    updateSession(s => ({ ...s, notes: text }));
  };

  const handleManualSave = () => {
    onSaveSessions(localSessions);
    setLastSaved(new Date());
  };

  const handleSubmit = () => {
    if (confirm("Sei sicuro di voler inviare questo blocco di 5 sessioni? I dati verranno archiviati.")) {
        onSubmitBlock(localSessions);
    }
  };

  // Logic for Performance Color (Red -> Green) mapped to 1-11
  const getPerformanceColorClass = (val: number) => {
    if (val <= 2) return 'bg-red-500 shadow-red-500/50 text-white';
    if (val <= 4) return 'bg-orange-500 shadow-orange-500/50 text-white';
    if (val <= 6) return 'bg-yellow-400 shadow-yellow-400/50 text-slate-900';
    if (val <= 8) return 'bg-lime-400 shadow-lime-400/50 text-slate-900';
    return 'bg-emerald-500 shadow-emerald-500/50 text-white';
  };

  // Logic for RPE text color (Intensity)
  const getRpeColor = (val: number) => {
    if (val < 4) return 'text-cyan-400';
    if (val < 7) return 'text-yellow-400';
    if (val < 9) return 'text-orange-400';
    return 'text-red-500';
  };

  // Specific labels for the 1-11 scale
  const getScaleLabel = (val: number) => {
    switch(val) {
      case 1: return "Molto molto poco";
      case 2: return "Molto poco";
      case 3: return "Moderatamente";
      case 5: return "Molto";
      case 7: return "Moltissimo";
      case 10: return "Estremamente elevato";
      case 11: return "Max pox";
      default: return "";
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950">
      {/* Header / Nav */}
      <div className="bg-slate-900 border-b border-slate-800 p-4 sticky top-0 z-20">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
            <div>
                 <h2 className="text-xl font-bold text-white tracking-tight">Diario Allenamento</h2>
                 <p className="text-xs text-slate-500">
                     {lastSaved ? `Ultimo salvataggio: ${lastSaved.toLocaleTimeString()}` : 'Modifiche non salvate'}
                 </p>
            </div>
            <div className="flex gap-2">
                <Button variant="secondary" size="sm" onClick={handleManualSave} className="gap-2">
                    <Save size={16} /> Salva Bozza
                </Button>
                <Button variant="primary" size="sm" onClick={handleSubmit} className="gap-2">
                    <Send size={16} /> Invia Blocco
                </Button>
            </div>
        </div>

        {/* Session Tabs */}
        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
            {localSessions.map((s, idx) => (
                <button
                    key={s.id}
                    onClick={() => setActiveSessionId(s.id)}
                    className={`flex flex-col items-center min-w-[4rem] p-2 rounded-lg border transition-all ${
                        activeSessionId === s.id 
                        ? 'bg-cyan-950/40 border-cyan-500 text-cyan-400' 
                        : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                    }`}
                >
                    <span className="text-xs font-bold uppercase">Sess {idx + 1}</span>
                    <span className="text-[10px] opacity-70 truncate w-full text-center">
                        {s.date ? new Date(s.date).toLocaleDateString('it-IT', {weekday:'short'}) : '-'}
                    </span>
                </button>
            ))}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 max-w-3xl mx-auto w-full space-y-8">

        {/* Date Selector */}
        <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800">
            <label className="text-slate-400 text-xs font-bold uppercase mb-2 block flex items-center gap-2">
                <Calendar size={14} /> Data Sessione
            </label>
            <input 
                type="date" 
                value={activeSession.date}
                onChange={(e) => updateSession(s => ({ ...s, date: e.target.value }))}
                className="bg-slate-950 border border-slate-700 rounded-lg px-4 py-2 text-white w-full sm:w-auto focus:border-cyan-500 outline-none"
            />
        </div>

        {/* RPE Scale */}
        <div className="bg-slate-900 rounded-xl border border-slate-800 p-6 shadow-lg relative overflow-hidden">
            <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-cyan-500 to-blue-600"></div>
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white">Scala RPE (Sforzo Percepito)</h3>
                <span className={`text-2xl font-black ${getRpeColor(activeSession.rpe)}`}>
                    {activeSession.rpe} <span className="text-sm text-slate-500 font-normal">/ 11</span>
                </span>
            </div>

            <input
                type="range"
                min="0"
                max="11"
                step="0.5"
                value={activeSession.rpe}
                onChange={(e) => handleRpeChange(parseFloat(e.target.value))}
                className="w-full h-3 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-500 hover:accent-cyan-400 transition-all"
            />
            <div className="flex justify-between text-xs text-slate-500 mt-2 font-mono">
                <span>Riposo</span>
                <span>Moderato</span>
                <span>Massimale</span>
            </div>
        </div>

        {/* Dynamic Parameters */}
        <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-200 flex items-center gap-2">
                Metriche di Valutazione
            </h3>

            {areas.length === 0 && (
                <div className="text-center p-8 border border-dashed border-slate-800 rounded-lg text-slate-500">
                    <AlertCircle className="mx-auto mb-2" />
                    Nessun parametro definito. Vai alle impostazioni.
                </div>
            )}

            {areas.map(area => (
                <div key={area.id} className="bg-slate-900/50 rounded-xl border border-slate-800/60 p-5">
                    <h4 className="text-cyan-400 font-bold mb-4 text-sm uppercase tracking-wider">{area.name}</h4>
                    <div className="space-y-8">
                        {area.parameters.length === 0 && <p className="text-xs text-slate-600 italic">Nessun parametro in quest'area</p>}
                        {area.parameters.map(param => {
                            const score = activeSession.scores[param.id] ?? 6;
                            const label = getScaleLabel(score);

                            return (
                                <div key={param.id} className="space-y-3">
                                    <div className="flex justify-between items-center">
                                        <div className="flex flex-col">
                                            <label className="text-slate-300 text-sm font-medium">{param.name}</label>
                                            {label && <span className="text-[10px] text-cyan-400 font-medium tracking-wide">{label}</span>}
                                        </div>
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm shadow-lg transition-all ${getPerformanceColorClass(score)}`}>
                                            {score}
                                        </div>
                                    </div>

                                    <div className="relative pt-1">
                                        {/* Ticks */}
                                        <div className="absolute w-full flex justify-between px-1 top-3 pointer-events-none opacity-30">
                                            {Array.from({length: 11}, (_, i) => i + 1).map(n => (
                                                <div key={n} className={`w-px h-1 bg-slate-400`}></div>
                                            ))}
                                        </div>

                                        <input
                                            type="range"
                                            min="1"
                                            max="11"
                                            step="1"
                                            value={score}
                                            onChange={(e) => handleScoreChange(param.id, parseInt(e.target.value))}
                                            className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-slate-500 z-10 relative"
                                        />

                                        {/* Visual Color Scale Below */}
                                        <div className="h-1.5 w-full mt-2 rounded-full flex overflow-hidden opacity-80">
                                            <div className="w-[18%] bg-red-500"></div> {/* 1-2 */}
                                            <div className="w-[18%] bg-orange-500"></div> {/* 3-4 */}
                                            <div className="w-[18%] bg-yellow-400"></div> {/* 5-6 */}
                                            <div className="w-[18%] bg-lime-400"></div> {/* 7-8 */}
                                            <div className="w-[28%] bg-emerald-500"></div> {/* 9-11 */}
                                        </div>
                                        <div className="flex justify-between text-[10px] text-slate-500 mt-1 uppercase font-bold tracking-wider">
                                            <span className="text-red-500">Molto Poco</span>
                                            <span className="text-emerald-500">Max Pox</span>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            ))}
        </div>

        {/* Notes */}
        <div className="bg-slate-900 rounded-xl border border-slate-800 p-5">
            <h3 className="text-sm font-bold text-slate-300 mb-3 uppercase">Note Sessione</h3>
            <textarea
                value={activeSession.notes}
                onChange={(e) => handleNotesChange(e.target.value)}
                placeholder="Come ti sei sentito oggi? Progressi tecnici? Stanchezza?"
                className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-slate-200 placeholder-slate-600 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-900 outline-none h-32 transition-colors resize-none"
            />
        </div>

        {/* Footer spacing */}
        <div className="h-12"></div>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { Area, TrainingBlock, SessionData } from '../types';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer,
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend
} from 'recharts';
import { Activity, TrendingUp, CalendarDays } from 'lucide-react';

interface CoachDashboardProps {
  currentBlockSessions: SessionData[];
  history: TrainingBlock[];
  currentAreas: Area[];
}

export const CoachDashboard: React.FC<CoachDashboardProps> = ({ 
  currentBlockSessions, 
  history,
  currentAreas
}) => {

  // --- 1. Data Prep for Radar Chart (Current Status) ---
  const radarData = useMemo(() => {
    // 1. Flatten all scores from current sessions
    const allScores: Record<string, number[]> = {}; // paramId -> [score1, score2...]

    currentBlockSessions.forEach(session => {
        Object.entries(session.scores).forEach(([pId, val]) => {
            if (!allScores[pId]) allScores[pId] = [];
            allScores[pId].push(val as number);
        });
    });

    // 2. Aggregate by Area
    return currentAreas.map(area => {
        let totalScore = 0;
        let count = 0;

        area.parameters.forEach(p => {
            const scores = allScores[p.id] || [];
            if (scores.length > 0) {
                totalScore += scores.reduce((a, b) => a + b, 0);
                count += scores.length;
            }
        });

        return {
            subject: area.name,
            A: count > 0 ? parseFloat((totalScore / count).toFixed(1)) : 0,
            fullMark: 11, // Scale is 11 now
        };
    });
  }, [currentBlockSessions, currentAreas]);

  // --- 2. Data Prep for Line Chart (History) ---
  const trendData = useMemo(() => {
    const dataPoints: any[] = [];

    // Helper to process a block
