    if (val <= 2) return '#ef4444'; // Red
    if (val <= 4) return '#f97316'; // Orange
    if (val <= 6) return '#facc15'; // Yellow
    if (val <= 8) return '#a3e635'; // Lime
    return '#10b981'; // Emerald
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 overflow-y-auto p-4 sm:p-6 space-y-8">

