                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                    <BarChart3 size={20} className="text-cyan-500" /> 
                    {selectedSessionId === 'all' ? 'Profilo Attuale (Media)' : 'Analisi Sessione Singola'}
                </h3>
                {selectedSessionId !== 'all' && (
                    <span className="text-xs bg-cyan-950 text-cyan-400 px-2 py-1 rounded border border-cyan-900">
                        {currentBlockSessions.find(s => s.id === selectedSessionId)?.label}
