                    </span>
                )}
            </div>

            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                        <XAxis 
                            dataKey="subject" 
                            stroke="#94a3b8" 
                            tick={{ fontSize: 11, fill: '#94a3b8' }} 
                            interval={0}
                        />
                        <YAxis 
                            domain={[0, 11]} 
                            stroke="#94a3b8" 
                            tick={{ fontSize: 12, fill: '#94a3b8' }}
                            tickCount={12}
                        />
                        <Tooltip 
                            cursor={{fill: '#1e293b', opacity: 0.4}}
                            contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', color: '#f8fafc' }}
                        />
                        <Bar dataKey="score" name="Valore" radius={[4, 4, 0, 0]}>
                            {chartData.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={getBarColor(entry.score)} />
                            ))}
                        </Bar>
                    </BarChart>
                </ResponsiveContainer>
            </div>
        </div>

        {/* QUICK STATS */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg flex flex-col">
             <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                <CalendarDays size={20} className="text-blue-500" /> Dettagli {selectedSessionId === 'all' ? 'Blocco' : 'Sessione'}
            </h3>

            <div className="grid grid-cols-2 gap-4 flex-1 content-start">
