import React, { useState, useEffect } from 'react';
import { Area, SessionData, TrainingBlock, DEFAULT_AREAS } from './types';
import { AthleteView } from './components/AthleteView';
import { SetupParameters } from './components/SetupParameters';
import { CoachDashboard } from './components/CoachDashboard';
import { Settings, User, LayoutDashboard } from 'lucide-react';

enum ViewState {
  ATHLETE = 'ATHLETE',
  SETUP = 'SETUP',
  COACH = 'COACH'
}

// Helper for random data generation
const randomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

// Generate 5 sessions with random data for DEMO purposes
const generateRandomBlock = (areas: Area[]): SessionData[] => {
  const now = new Date();
  return Array.from({ length: 5 }, (_, i) => {
    const scores: Record<string, number> = {};
    areas.forEach(area => {
        area.parameters.forEach(param => {
            // Generate realistic scores generally between 4 and 10
            scores[param.id] = randomInt(4, 10);
        });
    });

    const sessionDate = new Date(now);
    sessionDate.setDate(now.getDate() - (4 - i)); // Past 5 days

    return {
      id: `session-${Date.now()}-${i}`,
      label: `Sessione ${i + 1}`,
      date: sessionDate.toISOString().split('T')[0],
      rpe: randomInt(5, 9), // Random RPE
      scores: scores,
      notes: `Sessione simulata ${i + 1}. Feedback generato automaticamente. Sensazioni ${['buone', 'ottime', 'faticose', 'discrete'][randomInt(0, 3)]}.`,
      completed: true
    };
  });
};

// Empty block for reset
const generateEmptyBlock = (): SessionData[] => {
  return Array.from({ length: 5 }, (_, i) => ({
    id: `session-${Date.now()}-${i}`,
    label: `Sessione ${i + 1}`,
    date: '',
    rpe: 0,
    scores: {},
    notes: '',
    completed: false
  }));
};

