import React, { useState, useEffect } from 'react';
import { Area, SessionData, getAreaColor } from '../types';
import { Button } from './Button';
import { Save, Send, AlertCircle, Calendar } from 'lucide-react';

interface AthleteViewProps {
  areas: Area[];
  sessions: SessionData[];
  onSaveSessions: (sessions: SessionData[]) => void;
  onSubmitBlock: (sessions: SessionData[]) => void;
}

export const AthleteView: React.FC<AthleteViewProps> = ({ 
  areas, 
  sessions, 
  onSaveSessions, 
  onSubmitBlock 
}) => {
  const [activeSessionId, setActiveSessionId] = useState<string>(sessions[0].id);
  const [localSessions, setLocalSessions] = useState<SessionData[]>(sessions);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  // Sync local state when props change (external updates)
  useEffect(() => {
    setLocalSessions(sessions);
  }, [sessions]);

  const activeSession = localSessions.find(s => s.id === activeSessionId) || localSessions[0];

  const updateSession = (updater: (s: SessionData) => SessionData) => {
    const updated = localSessions.map(s => 
      s.id === activeSessionId ? updater(s) : s
    );
    setLocalSessions(updated);
  };

  const handleScoreChange = (paramId: string, value: number) => {
    updateSession(s => ({
      ...s,
      scores: { ...s.scores, [paramId]: value }
    }));
  };

  const handleRpeChange = (value: number) => {
    updateSession(s => ({ ...s, rpe: value }));
  };

  const handleNotesChange = (text: string) => {
    updateSession(s => ({ ...s, notes: text }));
  };

  const handleManualSave = () => {
    onSaveSessions(localSessions);
    setLastSaved(new Date());
  };

  const handleSubmit = () => {
    if (confirm("Sei sicuro di voler inviare questo blocco di 5 sessioni? I dati verranno archiviati.")) {
        onSubmitBlock(localSessions);
    }
  };

  // Logic for Performance Color (Red -> Green) mapped to 1-11
  const getPerformanceColorClass = (val: number) => {
    if (val <= 2) return 'bg-red-500 shadow-red-500/50 text-white';
    if (val <= 4) return 'bg-orange-500 shadow-orange-500/50 text-white';
    if (val <= 6) return 'bg-yellow-400 shadow-yellow-400/50 text-slate-900';
    if (val <= 8) return 'bg-lime-400 shadow-lime-400/50 text-slate-900';
    return 'bg-emerald-500 shadow-emerald-500/50 text-white';
  };

  // Logic for RPE text color (Intensity)
  const getRpeColor = (val: number) => {
    if (val < 4) return 'text-cyan-400';
    if (val < 7) return 'text-yellow-400';
    if (val < 9) return 'text-orange-400';
    return 'text-red-500';
  };

  // Specific labels for the 1-11 scale
  const getScaleLabel = (val: number) => {
    switch(val) {
      case 1: return "Molto molto poco";
      case 2: return "Molto poco";
      case 3: return "Moderatamente";
      case 5: return "Molto";
      case 7: return "Moltissimo";
      case 10: return "Estremamente elevato";
      case 11: return "Max pox";
      default: return "";
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950">
      {/* Header / Nav */}
      <div className="bg-slate-900 border-b border-slate-800 p-4 sticky top-0 z-20">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
            <div>
                 <h2 className="text-xl font-bold text-white tracking-tight">Diario Allenamento</h2>
                 <p className="text-xs text-slate-500">
                     {lastSaved ? `Ultimo salvataggio: ${lastSaved.toLocaleTimeString()}` : 'Modifiche non salvate'}
                 </p>
            </div>
            <div className="flex gap-2">
                <Button variant="secondary" size="sm" onClick={handleManualSave} className="gap-2">
                    <Save size={16} /> Salva Bozza
                </Button>
                <Button variant="primary" size="sm" onClick={handleSubmit} className="gap-2">
                    <Send size={16} /> Invia Blocco
                </Button>
            </div>
        </div>

        {/* Session Tabs */}
        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
            {localSessions.map((s, idx) => (
                <button
                    key={s.id}
                    onClick={() => setActiveSessionId(s.id)}
                    className={`flex flex-col items-center min-w-[4rem] p-2 rounded-lg border transition-all ${
                        activeSessionId === s.id 
                        ? 'bg-cyan-950/40 border-cyan-500 text-cyan-400' 
                        : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                    }`}
                >
                    <span className="text-xs font-bold uppercase">Sess {idx + 1}</span>
                    <span className="text-[10px] opacity-70 truncate w-full text-center">
                        {s.date ? new Date(s.date).toLocaleDateString('it-IT', {weekday:'short'}) : '-'}
                    </span>
                </button>
            ))}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 max-w-3xl mx-auto w-full space-y-8">

        {/* Date Selector */}
        <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800">
            <label className="text-slate-400 text-xs font-bold uppercase mb-2 block flex items-center gap-2">
                <Calendar size={14} /> Data Sessione
            </label>
            <input 
                type="date" 
                value={activeSession.date}
                onChange={(e) => updateSession(s => ({ ...s, date: e.target.value }))}
                className="bg-slate-950 border border-slate-700 rounded-lg px-4 py-2 text-white w-full sm:w-auto focus:border-cyan-500 outline-none"
            />
        </div>

        {/* RPE Scale */}
        <div className="bg-slate-900 rounded-xl border border-slate-800 p-6 shadow-lg relative overflow-hidden">
            <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-cyan-500 to-blue-600"></div>
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white">Scala RPE (Sforzo Percepito)</h3>
                <span className={`text-2xl font-black ${getRpeColor(activeSession.rpe)}`}>
                    {activeSession.rpe} <span className="text-sm text-slate-500 font-normal">/ 11</span>
                </span>
            </div>

            <input
                type="range"
                min="0"
                max="11"
                step="0.5"
                value={activeSession.rpe}
                onChange={(e) => handleRpeChange(parseFloat(e.target.value))}
                className="w-full h-3 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-500 hover:accent-cyan-400 transition-all"
            />
            <div className="flex justify-between text-xs text-slate-500 mt-2 font-mono">
                <span>Riposo</span>
                <span>Moderato</span>
                <span>Massimale</span>
            </div>
        </div>

        {/* Dynamic Parameters */}
        <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-200 flex items-center gap-2">
                Metriche di Valutazione
            </h3>

            {areas.length === 0 && (
                <div className="text-center p-8 border border-dashed border-slate-800 rounded-lg text-slate-500">
                    <AlertCircle className="mx-auto mb-2" />
                    Nessun parametro definito. Vai alle impostazioni.
                </div>
            )}

            {areas.map((area, index) => {
                const areaColor = getAreaColor(index);
                return (
                <div 
                    key={area.id} 
                    className="bg-slate-900/50 rounded-xl border border-slate-800/60 p-5 relative overflow-hidden"
                >
                    {/* Colored Indicator Line */}
                    <div className="absolute left-0 top-0 bottom-0 w-1" style={{ backgroundColor: areaColor }}></div>

                    <h4 className="font-bold mb-4 text-sm uppercase tracking-wider" style={{ color: areaColor }}>
                        {area.name}
                    </h4>
                    <div className="space-y-8">
                        {area.parameters.length === 0 && <p className="text-xs text-slate-600 italic">Nessun parametro in quest'area</p>}
                        {area.parameters.map(param => {
                            const score = activeSession.scores[param.id] ?? 6;
                            const label = getScaleLabel(score);

                            return (
                                <div key={param.id} className="space-y-3">
                                    <div className="flex justify-between items-center">
                                        <div className="flex flex-col">
                                            <label className="text-slate-300 text-sm font-medium">{param.name}</label>
                                            {label && <span className="text-[10px] opacity-80 font-medium tracking-wide" style={{ color: areaColor }}>{label}</span>}
                                        </div>
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm shadow-lg transition-all ${getPerformanceColorClass(score)}`}>
                                            {score}
                                        </div>
                                    </div>

                                    <div className="relative pt-1">
                                        {/* Ticks */}
                                        <div className="absolute w-full flex justify-between px-1 top-3 pointer-events-none opacity-30">
                                            {Array.from({length: 11}, (_, i) => i + 1).map(n => (
                                                <div key={n} className={`w-px h-1 bg-slate-400`}></div>
                                            ))}
                                        </div>

                                        <input
                                            type="range"
                                            min="1"
                                            max="11"
                                            step="1"
                                            value={score}
                                            onChange={(e) => handleScoreChange(param.id, parseInt(e.target.value))}
                                            className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-slate-500 z-10 relative"
                                        />

                                        {/* Visual Color Scale Below */}
                                        <div className="h-1.5 w-full mt-2 rounded-full flex overflow-hidden opacity-80">
                                            <div className="w-[18%] bg-red-500"></div> {/* 1-2 */}
                                            <div className="w-[18%] bg-orange-500"></div> {/* 3-4 */}
                                            <div className="w-[18%] bg-yellow-400"></div> {/* 5-6 */}
                                            <div className="w-[18%] bg-lime-400"></div> {/* 7-8 */}
                                            <div className="w-[28%] bg-emerald-500"></div> {/* 9-11 */}
                                        </div>
                                        <div className="flex justify-between text-[10px] text-slate-500 mt-1 uppercase font-bold tracking-wider">
                                            <span className="text-red-500">Molto Poco</span>
                                            <span className="text-emerald-500">Max Pox</span>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )})}
        </div>

        {/* Notes */}
        <div className="bg-slate-900 rounded-xl border border-slate-800 p-5">
            <h3 className="text-sm font-bold text-slate-300 mb-3 uppercase">Note Sessione</h3>
            <textarea
                value={activeSession.notes}
                onChange={(e) => handleNotesChange(e.target.value)}
                placeholder="Come ti sei sentito oggi? Progressi tecnici? Stanchezza?"
                className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-slate-200 placeholder-slate-600 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-900 outline-none h-32 transition-colors resize-none"
            />
        </div>

        {/* Footer spacing */}
        <div className="h-12"></div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Area, TrainingBlock, SessionData, getAreaColor } from '../types';
import { 
  BarChart, Bar, Cell, ResponsiveContainer,
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ReferenceLine
} from 'recharts';
import { 
  Activity, TrendingUp, TrendingDown, Minus, 
  CalendarDays, BarChart3, Filter, ChevronDown, ZoomIn
} from 'lucide-react';

interface CoachDashboardProps {
  currentBlockSessions: SessionData[];
  history: TrainingBlock[];
  currentAreas: Area[];
}

export const CoachDashboard: React.FC<CoachDashboardProps> = ({ 
  currentBlockSessions, 
  history,
  currentAreas
}) => {
  const [selectedSessionId, setSelectedSessionId] = useState<string>('all');
  const [selectedHistoryArea, setSelectedHistoryArea] = useState<string | null>(null);

  // --- 1. Data Prep for Bar Chart (Detailed Parameters) ---
  const chartData = useMemo(() => {
    let sessionsToAnalyze = currentBlockSessions;
    if (selectedSessionId !== 'all') {
        sessionsToAnalyze = currentBlockSessions.filter(s => s.id === selectedSessionId);
    }

    // Prepare an array of ALL parameters flattened
    const data: any[] = [];

    currentAreas.forEach((area, index) => {
        const areaColor = getAreaColor(index);

        area.parameters.forEach(param => {
            // Calculate avg for this parameter across selected sessions
            let total = 0;
            let count = 0;

            sessionsToAnalyze.forEach(s => {
                if (s.scores[param.id]) {
                    total += s.scores[param.id];
                    count++;
                }
            });

            const avg = count > 0 ? parseFloat((total / count).toFixed(1)) : 0;

            data.push({
                name: param.name,
                areaName: area.name,
                score: avg,
                color: areaColor,
                fullMark: 11
            });
        });
    });

    return data;
  }, [currentBlockSessions, currentAreas, selectedSessionId]);

  // --- 2. Data Prep for Line Chart (History + Drill Down) ---
  const trendData = useMemo(() => {
    const dataPoints: any[] = [];

    // Helper to process a block
    const processBlock = (blockLabel: string, sessions: SessionData[], areasSnapshot: Area[]) => {
        const point: any = { name: blockLabel };

        areasSnapshot.forEach(area => {
            // 1. Calculate Area Average
            let areaSum = 0;
            let areaCount = 0;
            const paramIds = new Set(area.parameters.map(p => p.id));

            // 2. Also calculate Individual Parameter Averages for this block
            const paramSums: Record<string, number> = {};
            const paramCounts: Record<string, number> = {};

            sessions.forEach(s => {
                Object.entries(s.scores).forEach(([pId, val]) => {
                    if (paramIds.has(pId)) {
                        areaSum += val as number;
                        areaCount++;

                        // Param specific
                        if(!paramSums[pId]) { paramSums[pId] = 0; paramCounts[pId] = 0; }
                        paramSums[pId] += val as number;
                        paramCounts[pId]++;
                    }
                });
            });

            point[area.name] = areaCount > 0 ? parseFloat((areaSum / areaCount).toFixed(1)) : 0;
            point[`${area.name}_id`] = area.id;

            // Add individual parameters to the point object
            area.parameters.forEach(p => {
                const pAvg = paramCounts[p.id] ? parseFloat((paramSums[p.id] / paramCounts[p.id]).toFixed(1)) : 0;
                // Use parameter name as key (make sure names are unique in display or use combination)
                point[`${p.name}`] = pAvg;
            });
        });

        if (Object.keys(point).length > 1) dataPoints.push(point);
    };

    history.forEach((block, idx) => {
        processBlock(`Blocco ${idx + 1}`, block.sessions, block.areaSnapshot);
    });

    const hasCurrentData = currentBlockSessions.some(s => Object.keys(s.scores).length > 0);
    if (hasCurrentData) {
        processBlock('Attuale', currentBlockSessions, currentAreas);
    }

    return dataPoints;
  }, [history, currentBlockSessions, currentAreas]);

  // --- 3. Trend Calculation (Cards) ---
  const trends = useMemo(() => {
    // Current averages per area (aggregated from flattened chartData)
    const currentAverages: Record<string, {sum: number, count: number, color: string}> = {};

    chartData.forEach(d => {
        if(!currentAverages[d.areaName]) currentAverages[d.areaName] = {sum:0, count:0, color: d.color};
        currentAverages[d.areaName].sum += d.score;
        currentAverages[d.areaName].count++;
    });

    // Last block averages
    const lastBlock = history.length > 0 ? history[history.length - 1] : null;
    const trendsList: any[] = [];

    currentAreas.forEach(area => {
        const currObj = currentAverages[area.name];
        const current = currObj && currObj.count > 0 ? parseFloat((currObj.sum / currObj.count).toFixed(1)) : 0;

        let previous = 0;
        if (lastBlock) {
             let sum = 0, count = 0;
             const paramIds = new Set(area.parameters.map(p => p.id));
             lastBlock.sessions.forEach(s => {
                 Object.entries(s.scores).forEach(([pid, v]) => {
                     if (paramIds.has(pid)) { sum += (v as number); count++; }
                 });
             });
             previous = count > 0 ? parseFloat((sum/count).toFixed(1)) : 0;
        }

        const diff = current - previous;
        trendsList.push({
            id: area.id,
            name: area.name,
            current,
            previous,
            diff,
            isImproving: diff > 0,
            isStable: diff === 0,
            color: currObj ? currObj.color : '#64748b'
        });
    });
    return trendsList;
  }, [chartData, history, currentAreas]);

  // Determine lines to show in History Chart
  const linesToShow = useMemo(() => {
      if (!selectedHistoryArea) {
          // Show Area Averages
          return currentAreas.map((area, index) => ({
              key: area.name,
              color: getAreaColor(index),
              strokeWidth: 3
          }));
      } else {
          // Show Parameters for selected Area
          const area = currentAreas.find(a => a.name === selectedHistoryArea);
          if (!area) return [];
          const areaIndex = currentAreas.indexOf(area);
          const baseColor = getAreaColor(areaIndex);

          return area.parameters.map((p, idx) => ({
              key: p.name,
              // Generate shades or variations if possible, else use same color with opacity or dashed
              color: baseColor, 
              strokeWidth: 2,
              strokeDasharray: idx % 2 === 0 ? "0" : "5 5" // Differentiate lines visually
          }));
      }
  }, [selectedHistoryArea, currentAreas]);

  return (
    <div className="flex flex-col h-full bg-slate-950 overflow-y-auto p-4 sm:p-6 space-y-8">

      {/* HEADER & CONTROLS */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-slate-800 pb-6">
        <div>
            <h2 className="text-2xl font-bold text-white flex items-center gap-3">
            <Activity className="text-cyan-400" /> 
            Dashboard Coach
            </h2>
            <p className="text-slate-400 text-sm">Analisi dettagliata delle performance.</p>
        </div>

        {/* SESSION SELECTOR */}
        <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                <Filter size={16} />
            </div>
            <select 
                value={selectedSessionId}
                onChange={(e) => setSelectedSessionId(e.target.value)}
                className="bg-slate-900 border border-slate-700 text-white text-sm rounded-lg focus:ring-cyan-500 focus:border-cyan-500 block w-full pl-10 p-2.5 appearance-none pr-10 outline-none hover:bg-slate-800 transition-colors cursor-pointer"
            >
                <option value="all">Media Intero Blocco</option>
                <option disabled>───────</option>
                {currentBlockSessions.map((s, idx) => (
                    <option key={s.id} value={s.id}>
                        {s.label} ({s.date ? new Date(s.date).toLocaleDateString('it-IT') : 'No data'})
                    </option>
                ))}
            </select>
            <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none text-slate-400">
                <ChevronDown size={16} />
            </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* BAR CHART: DETAILED PARAMETERS */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                    <BarChart3 size={20} className="text-cyan-500" /> 
                    {selectedSessionId === 'all' ? 'Dettaglio Parametri (Media Blocco)' : 'Dettaglio Parametri Sessione'}
                </h3>
            </div>

            <div className="h-[350px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 40 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                        <XAxis 
                            dataKey="name" 
                            stroke="#94a3b8" 
                            tick={{ fontSize: 10, fill: '#94a3b8' }} 
                            interval={0}
                            angle={-45}
                            textAnchor="end"
                        />
                        <YAxis 
                            domain={[0, 11]} 
                            stroke="#94a3b8" 
                            tick={{ fontSize: 12, fill: '#94a3b8' }}
                            tickCount={12}
                        />
                        <Tooltip 
                            cursor={{fill: '#1e293b', opacity: 0.4}}
                            contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', color: '#f8fafc' }}
                            itemStyle={{ color: '#fff' }}
                            formatter={(value: number) => [value, 'Punteggio']}
                        />
                        <Bar dataKey="score" name="Valore" radius={[4, 4, 0, 0]}>
                            {chartData.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={entry.color} />
                            ))}
                        </Bar>
                    </BarChart>
                </ResponsiveContainer>
            </div>
        </div>

        {/* QUICK STATS (Full Width or compact) */}
        {/* Keeping stats compact for layout balance */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg flex flex-col justify-center lg:col-span-2">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-slate-950 p-4 rounded-lg border border-slate-800">
                    <span className="text-slate-500 text-xs uppercase font-bold">RPE {selectedSessionId === 'all' ? 'Medio' : ''}</span>
                    <div className="text-3xl font-mono text-white mt-1">
                        {selectedSessionId === 'all' ? (
                            (() => {
                                let totalRpe = 0, count = 0;
                                currentBlockSessions.forEach(s => { if(s.rpe>0) { totalRpe+=s.rpe; count++; }});
                                return count ? (totalRpe/count).toFixed(1) : '-';
                            })()
                        ) : (
                            currentBlockSessions.find(s => s.id === selectedSessionId)?.rpe || '-'
                        )}
                    </div>
                </div>
                 <div className="bg-slate-950 p-4 rounded-lg border border-slate-800">
                    <span className="text-slate-500 text-xs uppercase font-bold">Intensità</span>
                    <div className="text-lg font-medium text-slate-300 mt-2">
                        {(() => {
                            const rpe = selectedSessionId === 'all' 
                                ? parseFloat((currentBlockSessions.reduce((acc, s) => acc + s.rpe, 0) / (currentBlockSessions.filter(s => s.rpe > 0).length || 1)).toFixed(1))
                                : currentBlockSessions.find(s => s.id === selectedSessionId)?.rpe || 0;

                            if (rpe < 4) return <span className="text-cyan-400">Leggera</span>;
                            if (rpe < 7) return <span className="text-yellow-400">Moderata</span>;
                            if (rpe < 9) return <span className="text-orange-400">Alta</span>;
                            return <span className="text-red-500 font-bold">Massimale</span>;
                        })()}
                    </div>
                </div>
                <div className="bg-slate-950 p-4 rounded-lg border border-slate-800 col-span-2">
                     <span className="text-slate-500 text-xs uppercase font-bold">Note</span>
                     <p className="text-sm text-slate-300 mt-1 truncate">
                        {selectedSessionId === 'all' ? 'Seleziona una sessione per vedere le note.' : currentBlockSessions.find(s => s.id === selectedSessionId)?.notes || '-'}
                     </p>
                </div>
            </div>
        </div>
      </div>

      {/* TREND ANALYSIS SECTION */}
      <div>
        <div className="flex items-center gap-3 mb-4">
            <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <TrendingUp size={20} className="text-purple-500" /> Analisi Andamento
            </h3>
            {selectedHistoryArea && (
                <span className="text-sm bg-slate-800 text-white px-2 py-1 rounded border border-slate-700 animate-pulse">
                    Filtro Attivo: <span className="font-bold">{selectedHistoryArea}</span>
                </span>
            )}
        </div>

        <p className="text-slate-400 text-sm mb-4">
            Clicca su una tessera per analizzare i <strong>parametri specifici</strong> di quell'area nel tempo.
        </p>

        {/* TREND CARDS GRID */}
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 mb-6">
            <button
                onClick={() => setSelectedHistoryArea(null)}
                className={`p-3 rounded-xl border transition-all text-left ${
                    selectedHistoryArea === null 
                    ? 'bg-slate-800 border-white/20 ring-1 ring-white/20' 
                    : 'bg-slate-900 border-slate-800 hover:bg-slate-800'
                }`}
            >
                <span className="text-xs text-slate-400 font-bold uppercase block mb-1">Generale</span>
                <span className="text-sm text-white">Medie Aree</span>
            </button>

            {trends.map(t => (
                <button 
                    key={t.id}
                    onClick={() => setSelectedHistoryArea(selectedHistoryArea === t.name ? null : t.name)}
                    className={`p-3 rounded-xl border transition-all text-left relative overflow-hidden ${
                        selectedHistoryArea === t.name
                        ? 'bg-slate-800 ring-1' 
                        : 'bg-slate-900 border-slate-800 hover:bg-slate-800'
                    }`}
                    style={{ borderColor: selectedHistoryArea === t.name ? t.color : '#1e293b', ringColor: t.color }}
                >   
                    <div className="absolute top-0 right-0 w-8 h-8 opacity-10 rounded-bl-full" style={{background: t.color}}></div>

                    <div className="flex justify-between items-start mb-2">
                        <span className="text-xs font-bold uppercase truncate pr-2" style={{ color: t.color }}>{t.name}</span>
                        {history.length > 0 && (
                            t.isStable ? <Minus size={14} className="text-slate-500" /> :
                            t.isImproving 
                            ? <TrendingUp size={14} className="text-emerald-400" /> 
                            : <TrendingDown size={14} className="text-red-400" />
                        )}
                    </div>
                    <div className="flex items-end gap-2">
                        <span className="text-xl font-bold text-white">
                            {t.current}
                        </span>
                        {history.length > 0 && (
                            <span className={`text-xs mb-1 ${t.isImproving ? 'text-emerald-400' : t.isStable ? 'text-slate-500' : 'text-red-400'}`}>
                                {t.diff > 0 ? '+' : ''}{t.diff.toFixed(1)}
                            </span>
                        )}
                    </div>
                </button>
            ))}
        </div>

        {/* HISTORICAL CHART */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg">
            <div className="h-[400px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={trendData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                        <XAxis dataKey="name" stroke="#94a3b8" />
                        <YAxis domain={[0, 11]} stroke="#94a3b8" />
                        <Tooltip 
                             contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', color: '#f8fafc' }}
                        />
                        <Legend wrapperStyle={{ paddingTop: '10px' }}/>

                        {/* Dynamic Lines based on selection */}
                        {linesToShow.map((line) => (
                            <Line 
                                key={line.key}
                                type="monotone" 
                                dataKey={line.key} 
                                stroke={line.color} 
                                strokeWidth={line.strokeWidth}
                                strokeDasharray={line.strokeDasharray}
                                dot={{ fill: '#0f172a', strokeWidth: 2, r: 4 }}
                                activeDot={{ r: 6 }}
                                animationDuration={500}
                            />
                        ))}
                    </LineChart>
                </ResponsiveContainer>
            </div>
            <div className="flex justify-center mt-4 gap-4 text-xs text-slate-500">
                <div className="flex items-center gap-2">
                    <ZoomIn size={14} />
                    <span>{selectedHistoryArea ? `Visualizzazione dettaglio parametri per ${selectedHistoryArea}` : 'Visualizzazione media complessiva per Area'}</span>
                </div>
            </div>
        </div>
      </div>

      <div className="h-12"></div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Area, TrainingBlock, SessionData, getAreaColor } from '../types';
import { 
  BarChart, Bar, Cell, ResponsiveContainer,
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend
} from 'recharts';
import { 
  Activity, TrendingUp, TrendingDown, Minus, 
  BarChart3, Filter, ChevronDown, ZoomIn, History, PlayCircle
} from 'lucide-react';

interface CoachDashboardProps {
  currentBlockSessions: SessionData[];
  history: TrainingBlock[];
  currentAreas: Area[];
}

export const CoachDashboard: React.FC<CoachDashboardProps> = ({ 
  currentBlockSessions, 
  history,
  currentAreas
}) => {
  const [selectedSessionId, setSelectedSessionId] = useState<string>('all');
  const [selectedHistoryArea, setSelectedHistoryArea] = useState<string | null>(null);

  // New State: Toggle between Macro (Blocks) and Micro (Current Sessions) view
  const [trendViewMode, setTrendViewMode] = useState<'macro' | 'micro'>('micro');

  // --- 1. Data Prep for Bar Chart (Detailed Parameters) ---
  const chartData = useMemo(() => {
    let sessionsToAnalyze = currentBlockSessions;
    if (selectedSessionId !== 'all') {
        sessionsToAnalyze = currentBlockSessions.filter(s => s.id === selectedSessionId);
    }

    const data: any[] = [];

    currentAreas.forEach((area, index) => {
        const areaColor = getAreaColor(index);

        area.parameters.forEach(param => {
            let total = 0;
            let count = 0;

            sessionsToAnalyze.forEach(s => {
                if (s.scores[param.id]) {
                    total += s.scores[param.id];
                    count++;
                }
            });

            const avg = count > 0 ? parseFloat((total / count).toFixed(1)) : 0;

            data.push({
                name: param.name,
                areaName: area.name,
                score: avg,
                color: areaColor,
                fullMark: 11
            });
        });
    });

    return data;
  }, [currentBlockSessions, currentAreas, selectedSessionId]);

  // --- 2. Data Prep for MACRO Trend (History of Blocks) ---
  const macroTrendData = useMemo(() => {
    const dataPoints: any[] = [];

    const processBlock = (blockLabel: string, sessions: SessionData[], areasSnapshot: Area[]) => {
        const point: any = { name: blockLabel };

        areasSnapshot.forEach(area => {
            let areaSum = 0;
            let areaCount = 0;
            const paramIds = new Set(area.parameters.map(p => p.id));

            // Parameter specifics calculators
            const paramSums: Record<string, number> = {};
            const paramCounts: Record<string, number> = {};

            sessions.forEach(s => {
                Object.entries(s.scores).forEach(([pId, val]) => {
                    if (paramIds.has(pId)) {
                        areaSum += val as number;
                        areaCount++;

                        if(!paramSums[pId]) { paramSums[pId] = 0; paramCounts[pId] = 0; }
                        paramSums[pId] += val as number;
                        paramCounts[pId]++;
                    }
                });
            });

            point[area.name] = areaCount > 0 ? parseFloat((areaSum / areaCount).toFixed(1)) : 0;
            point[`${area.name}_id`] = area.id;

            area.parameters.forEach(p => {
                const pAvg = paramCounts[p.id] ? parseFloat((paramSums[p.id] / paramCounts[p.id]).toFixed(1)) : 0;
                point[`${p.name}`] = pAvg;
            });
        });

        if (Object.keys(point).length > 1) dataPoints.push(point);
    };

    history.forEach((block, idx) => {
        processBlock(`Blocco ${idx + 1}`, block.sessions, block.areaSnapshot);
    });

    // Add current block as the last point in Macro view
    const hasCurrentData = currentBlockSessions.some(s => Object.keys(s.scores).length > 0);
    if (hasCurrentData) {
        processBlock('Attuale', currentBlockSessions, currentAreas);
    }

    return dataPoints;
  }, [history, currentBlockSessions, currentAreas]);

  // --- 3. Data Prep for MICRO Trend (Sessions within current block) ---
  const microTrendData = useMemo(() => {
    return currentBlockSessions.map((session, i) => {
        // Use shorter label for X-Axis
        const point: any = { name: `S${i + 1}` };

        currentAreas.forEach(area => {
            let areaSum = 0;
            let areaCount = 0;

            area.parameters.forEach(p => {
                const val = session.scores[p.id];
                // Add individual parameter score to data point
                point[p.name] = val !== undefined ? val : null;

                if (val !== undefined) {
                    areaSum += val;
                    areaCount++;
                }
            });

            // Add Area Average to data point
            point[area.name] = areaCount > 0 ? parseFloat((areaSum / areaCount).toFixed(1)) : null;
        });

        return point;
    });
  }, [currentBlockSessions, currentAreas]);

  // --- 4. Trend Stats Cards Calculation ---
  const trends = useMemo(() => {
    const currentAverages: Record<string, {sum: number, count: number, color: string}> = {};
    chartData.forEach(d => {
        if(!currentAverages[d.areaName]) currentAverages[d.areaName] = {sum:0, count:0, color: d.color};
        currentAverages[d.areaName].sum += d.score;
        currentAverages[d.areaName].count++;
    });

    const lastBlock = history.length > 0 ? history[history.length - 1] : null;
    const trendsList: any[] = [];

    currentAreas.forEach(area => {
        const currObj = currentAverages[area.name];
        const current = currObj && currObj.count > 0 ? parseFloat((currObj.sum / currObj.count).toFixed(1)) : 0;

        let previous = 0;
        if (lastBlock) {
             let sum = 0, count = 0;
             const paramIds = new Set(area.parameters.map(p => p.id));
             lastBlock.sessions.forEach(s => {
                 Object.entries(s.scores).forEach(([pid, v]) => {
                     if (paramIds.has(pid)) { sum += (v as number); count++; }
                 });
             });
             previous = count > 0 ? parseFloat((sum/count).toFixed(1)) : 0;
        }

        const diff = current - previous;
        trendsList.push({
            id: area.id,
            name: area.name,
            current,
            previous,
            diff,
            isImproving: diff > 0,
            isStable: diff === 0,
            color: currObj ? currObj.color : '#64748b'
        });
    });
    return trendsList;
  }, [chartData, history, currentAreas]);

  // --- 5. Determine Lines to Show ---
  const linesToShow = useMemo(() => {
      if (!selectedHistoryArea) {
          // Show Area Averages
          return currentAreas.map((area, index) => ({
              key: area.name,
              color: getAreaColor(index),
              strokeWidth: 3,
              strokeDasharray: "0"
          }));
      } else {
          // Show Parameters for selected Area
          const area = currentAreas.find(a => a.name === selectedHistoryArea);
          if (!area) return [];
          const areaIndex = currentAreas.indexOf(area);
          const baseColor = getAreaColor(areaIndex);

          return area.parameters.map((p, idx) => ({
              key: p.name,
              color: baseColor, 
              strokeWidth: 2,
              strokeDasharray: idx % 2 === 0 ? "0" : "5 5" // Visual differentiation
          }));
      }
  }, [selectedHistoryArea, currentAreas]);

  return (
    <div className="flex flex-col h-full bg-slate-950 overflow-y-auto p-4 sm:p-6 space-y-8">

      {/* HEADER & CONTROLS */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-slate-800 pb-6">
        <div>
            <h2 className="text-2xl font-bold text-white flex items-center gap-3">
            <Activity className="text-cyan-400" /> 
            Dashboard Coach
            </h2>
            <p className="text-slate-400 text-sm">Analisi dettagliata delle performance.</p>
        </div>

        {/* SESSION SELECTOR */}
        <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                <Filter size={16} />
            </div>
            <select 
                value={selectedSessionId}
                onChange={(e) => setSelectedSessionId(e.target.value)}
                className="bg-slate-900 border border-slate-700 text-white text-sm rounded-lg focus:ring-cyan-500 focus:border-cyan-500 block w-full pl-10 p-2.5 appearance-none pr-10 outline-none hover:bg-slate-800 transition-colors cursor-pointer"
            >
                <option value="all">Media Intero Blocco</option>
                <option disabled>───────</option>
                {currentBlockSessions.map((s, idx) => (
                    <option key={s.id} value={s.id}>
                        {s.label} ({s.date ? new Date(s.date).toLocaleDateString('it-IT') : 'No data'})
                    </option>
                ))}
            </select>
            <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none text-slate-400">
                <ChevronDown size={16} />
            </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* BAR CHART: DETAILED PARAMETERS */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-lg lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                    <BarChart3 size={20} className="text-cyan-500" /> 
                    {selectedSessionId === 'all' ? 'Dettaglio Parametri (Media Blocco)' : 'Dettaglio Parametri Sessione'}
                </h3>
            </div>

            <div className="h-[350px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 40 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                        <XAxis 
                            dataKey="name" 
                            stroke="#94a3b8" 
                            tick={{ fontSize: 10, fill: '#94a3b8' }} 
                            interval={0}
                            angle={-45}
                            textAnchor="end"
                        />
                        <YAxis 
                            domain={[0, 11]} 
                            stroke="#94a3b8" 
                            tick={{ fontSize: 12, fill: '#94a3b8' }}
                            tickCount={12}
                        />
                        <Tooltip 
                            cursor={{fill: '#1e293b', opacity: 0.4}}
                            contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', color: '#f8fafc' }}
                            itemStyle={{ color: '#fff' }}
                            formatter={(value: number) => [value, 'Punteggio']}
                        />
                        <Bar dataKey="score" name="Valore" radius={[4, 4, 0, 0]}>
                            {chartData.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={entry.color} />
                            ))}
                        </Bar>
                    </BarChart>
                </ResponsiveContainer>
            </div>
        </div>
      </div>

      {/* TREND ANALYSIS SECTION */}
      <div>
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4 mb-6">
            <div>
                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                    <TrendingUp size={20} className="text-purple-500" /> Analisi Andamento
                </h3>
                <p className="text-slate-400 text-sm mt-1">
                    Seleziona una tessera per filtrare e la vista temporale per il dettaglio.
                </p>
            </div>

            {/* TIME VIEW TOGGLE */}
            <div className="bg-slate-900 p-1 rounded-lg border border-slate-700 flex gap-1">
                <button
                    onClick={() => setTrendViewMode('micro')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        trendViewMode === 'micro' 
                        ? 'bg-purple-600 text-white shadow-lg' 
                        : 'text-slate-400 hover:text-white hover:bg-slate-800'
                    }`}
                >
                    <PlayCircle size={14} /> Sessioni Attuali (5)
                </button>
                <button
                    onClick={() => setTrendViewMode('macro')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        trendViewMode === 'macro' 
                        ? 'bg-purple-600 text-white shadow-lg' 
                        : 'text-slate-400 hover:text-white hover:bg-slate-800'
                    }`}
