        >
          <Settings size={20} />
        </button>
      </div>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden relative">
         {isSetupOpen ? (
            <div className="absolute inset-0 z-40 bg-slate-950">
               <SetupParameters 
                  areas={areas}
