// --- DATA LOGIC ---

const randomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

// Generate random data specifically for a given ID if empty
const generateRandomBlock = (areas: Area[]): SessionData[] => {
  const now = new Date();
  return Array.from({ length: 5 }, (_, i) => {
    const scores: Record<string, number> = {};
    areas.forEach(area => {
        area.parameters.forEach(param => {
            scores[param.id] = randomInt(4, 10);
        });
    });
    const sessionDate = new Date(now);
    sessionDate.setDate(now.getDate() - (4 - i));

    return {
      id: `session-${Date.now()}-${i}`,
      label: `Sessione ${i + 1}`,
      date: sessionDate.toISOString().split('T')[0],
      rpe: randomInt(5, 9),
      scores: scores,
      notes: `Sessione generata per test. Sensazioni variabili.`,
      completed: true
    };
  });
};

const generateEmptyBlock = (): SessionData[] => {
  return Array.from({ length: 5 }, (_, i) => ({
    id: `session-${Date.now()}-${i}`,
    label: `Sessione ${i + 1}`,
    date: '',
    rpe: 0,
    scores: {},
    notes: '',
    completed: false
  }));
};

// --- CUSTOM HOOK FOR NAMESPACED DATA ---
// Loads/Saves data based on the "athleteId" prefix
const useAthleteData = (athleteId: string) => {
  const storageKey = (suffix: string) => `flux_${athleteId}_${suffix}`;

  const [areas, setAreas] = useState<Area[]>(() => {
    const saved = localStorage.getItem(storageKey('areas'));
    return saved ? JSON.parse(saved) : DEFAULT_AREAS;
  });

  const [currentSessions, setCurrentSessions] = useState<SessionData[]>(() => {
    const saved = localStorage.getItem(storageKey('current_block'));
    let data = saved ? JSON.parse(saved) : null;

    const isEffectivelyEmpty = !data || data.every((s: any) => s.rpe === 0 && Object.keys(s.scores).length === 0);

    if (isEffectivelyEmpty) {
        return generateRandomBlock(areas);
    }
    return data;
  });

  const [history, setHistory] = useState<TrainingBlock[]>(() => {
    const saved = localStorage.getItem(storageKey('history'));
    return saved ? JSON.parse(saved) : [];
  });

  // Persistence Effects
  useEffect(() => { localStorage.setItem(storageKey('areas'), JSON.stringify(areas)); }, [areas, athleteId]);
  useEffect(() => { localStorage.setItem(storageKey('current_block'), JSON.stringify(currentSessions)); }, [currentSessions, athleteId]);
  useEffect(() => { localStorage.setItem(storageKey('history'), JSON.stringify(history)); }, [history, athleteId]);

  const handleSubmitBlock = (finalSessions: SessionData[]) => {
    const newBlock: TrainingBlock = {
        id: `block-${Date.now()}`,
        submittedAt: new Date().toISOString(),
        areaSnapshot: JSON.parse(JSON.stringify(areas)),
        sessions: finalSessions
    };
    setHistory([...history, newBlock]);
    setCurrentSessions(generateEmptyBlock());
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return {
    areas, setAreas,
    currentSessions, setCurrentSessions,
    history, setHistory,
    handleSubmitBlock
  };
};

