                    }`}
                >
                    <span className="text-xs font-black uppercase tracking-wider">Sess {idx + 1}</span>
                    <span className="text-[10px] opacity-70 truncate w-full text-center">
                        {s.date ? new Date(s.date).toLocaleDateString('it-IT', {weekday:'short'}) : '-'}
                    </span>
                </button>
            ))}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 max-w-3xl mx-auto w-full space-y-8">

        {/* Date Selector */}
        <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800 hover:border-slate-700 transition-colors">
            <label className="text-cyan-400 text-xs font-bold uppercase mb-2 block flex items-center gap-2 tracking-wider">
                <Calendar size={14} className="text-cyan-400" /> Data Sessione
            </label>
            <input 
                type="date" 
                value={activeSession.date}
                onChange={(e) => updateSession(s => ({ ...s, date: e.target.value }))}
                className="bg-slate-950 border border-slate-700 rounded-lg px-4 py-2 text-white w-full sm:w-auto focus:border-cyan-500 focus:shadow-[0_0_10px_rgba(6,182,212,0.2)] outline-none transition-all"
            />
        </div>

        {/* RPE Scale */}
        <div className="bg-slate-900 rounded-xl border border-slate-800 p-6 shadow-xl relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-cyan-400 to-blue-600 shadow-[0_0_10px_rgba(34,211,238,0.5)]"></div>
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white group-hover:text-cyan-100 transition-colors">RPE <span className="text-xs font-normal text-slate-500 uppercase tracking-wide ml-2">Sforzo Percepito</span></h3>
                <span className={`text-3xl font-black ${getRpeColor(activeSession.rpe)}`}>
                    {activeSession.rpe} <span className="text-sm text-slate-500 font-normal opacity-50">/ 11</span>
                </span>
            </div>

            <input
                type="range"
                min="0"
                max="11"
                step="0.5"
                value={activeSession.rpe}
                onChange={(e) => handleRpeChange(parseFloat(e.target.value))}
                className="w-full h-3 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-400 hover:accent-cyan-300 transition-all"
            />
            <div className="flex justify-between text-xs text-slate-500 mt-2 font-mono uppercase tracking-wide">
                <span>Riposo</span>
                <span className="text-cyan-500/50">Moderato</span>
                <span className="text-red-500/50">Massimale</span>
            </div>
        </div>

        {/* Dynamic Parameters */}
        <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-200 flex items-center gap-2 uppercase tracking-widest text-xs opacity-70">
                Metriche Valutazione
            </h3>

            {areas.length === 0 && (
                <div className="text-center p-8 border border-dashed border-slate-800 rounded-lg text-slate-500">
                    <AlertCircle className="mx-auto mb-2" />
                    Nessun parametro definito. Vai alle impostazioni.
                </div>
            )}

            {areas.map((area, index) => {
                const areaColor = getAreaColor(index);
                return (
                <div 
                    key={area.id} 
                    className="bg-slate-900/50 rounded-xl border border-slate-800/60 p-5 relative overflow-hidden transition-all hover:border-slate-700 hover:shadow-[0_0_15px_rgba(0,0,0,0.3)]"
                >
                    {/* Colored Indicator Line */}
                    <div className="absolute left-0 top-0 bottom-0 w-1 shadow-[0_0_8px]" style={{ backgroundColor: areaColor, color: areaColor }}></div>

                    <h4 className="font-black mb-6 text-sm uppercase tracking-widest flex items-center gap-2" style={{ color: areaColor, textShadow: `0 0 10px ${areaColor}40` }}>
                        {area.name}
                    </h4>
                    <div className="space-y-8">
                        {area.parameters.length === 0 && <p className="text-xs text-slate-600 italic">Nessun parametro in quest'area</p>}
                        {area.parameters.map(param => {
                            const score = activeSession.scores[param.id] ?? 6;
                            const label = getScaleLabel(score);

                            return (
                                <div key={param.id} className="space-y-3">
                                    <div className="flex justify-between items-center">
                                        <div className="flex flex-col">
                                            <label className="text-slate-200 text-sm font-bold tracking-wide">{param.name}</label>
                                            {label && <span className="text-[10px] font-bold tracking-wider mt-0.5 opacity-90" style={{ color: areaColor }}>{label}</span>}
                                        </div>
                                        <div className={`w-9 h-9 rounded-lg flex items-center justify-center font-black text-sm shadow-lg transition-all border border-white/10 ${getPerformanceColorClass(score)}`}>
                                            {score}
                                        </div>
                                    </div>

                                    <div className="relative pt-1">
                                        {/* Ticks */}
                                        <div className="absolute w-full flex justify-between px-1 top-3 pointer-events-none opacity-30">
                                            {Array.from({length: 11}, (_, i) => i + 1).map(n => (
                                                <div key={n} className={`w-px h-1 bg-slate-400`}></div>
                                            ))}
                                        </div>

                                        <input
                                            type="range"
                                            min="1"
                                            max="11"
                                            step="1"
                                            value={score}
                                            onChange={(e) => handleScoreChange(param.id, parseInt(e.target.value))}
                                            className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-slate-400 hover:accent-white z-10 relative"
                                        />

                                        {/* Visual Color Scale Below */}
                                        <div className="h-1.5 w-full mt-2 rounded-full flex overflow-hidden opacity-80 shadow-inner">
                                            <div className="w-[18%] bg-red-600"></div> {/* 1-2 */}
                                            <div className="w-[18%] bg-orange-500"></div> {/* 3-4 */}
                                            <div className="w-[18%] bg-yellow-400"></div> {/* 5-6 */}
                                            <div className="w-[18%] bg-lime-400"></div> {/* 7-8 */}
                                            <div className="w-[28%] bg-emerald-500"></div> {/* 9-11 */}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )})}
        </div>

        {/* Notes */}
        <div className="bg-slate-900 rounded-xl border border-slate-800 p-5 shadow-lg">
            <h3 className="text-xs font-bold text-slate-400 mb-3 uppercase tracking-widest flex items-center gap-2">
                Note Sessione
            </h3>
            <textarea
                value={activeSession.notes}
                onChange={(e) => handleNotesChange(e.target.value)}
                placeholder="Come ti sei sentito oggi? Progressi tecnici? Stanchezza?"
                className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-slate-200 placeholder-slate-600 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-900 focus:shadow-[0_0_15px_rgba(6,182,212,0.1)] outline-none h-32 transition-colors resize-none text-sm"
            />
        </div>

        {/* Author Credit Footer */}
        <div className="pt-8 pb-4 border-t border-slate-800/50 mt-12">
            <div className="text-center opacity-70">
                <p className="text-[10px] uppercase tracking-[0.2em] font-bold text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-purple-400 drop-shadow-[0_0_8px_rgba(34,211,238,0.4)]">
                    Dr. Massimiliano Di Liborio
                </p>
            </div>
        </div>

        {/* Bottom padding */}
        <div className="h-8"></div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Area, TrainingBlock, SessionData, getAreaColor } from '../types';
import { 
  BarChart, Bar, Cell, ResponsiveContainer,
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend
} from 'recharts';
import { 
  Activity, TrendingUp, TrendingDown, Minus, 
  BarChart3, Filter, ChevronDown, ZoomIn, History, PlayCircle
} from 'lucide-react';

interface CoachDashboardProps {
  currentBlockSessions: SessionData[];
  history: TrainingBlock[];
  currentAreas: Area[];
}

export const CoachDashboard: React.FC<CoachDashboardProps> = ({ 
  currentBlockSessions, 
  history,
  currentAreas
}) => {
  const [selectedSessionId, setSelectedSessionId] = useState<string>('all');
  const [selectedHistoryArea, setSelectedHistoryArea] = useState<string | null>(null);

  // New State: Toggle between Macro (Blocks) and Micro (Current Sessions) view
  const [trendViewMode, setTrendViewMode] = useState<'macro' | 'micro'>('micro');

  // --- 1. Data Prep for Bar Chart (Detailed Parameters) ---
  const chartData = useMemo(() => {
    let sessionsToAnalyze = currentBlockSessions;
    if (selectedSessionId !== 'all') {
        sessionsToAnalyze = currentBlockSessions.filter(s => s.id === selectedSessionId);
    }

    const data: any[] = [];

    currentAreas.forEach((area, index) => {
        const areaColor = getAreaColor(index);

        area.parameters.forEach(param => {
            let total = 0;
            let count = 0;

            sessionsToAnalyze.forEach(s => {
                if (s.scores[param.id]) {
                    total += s.scores[param.id];
                    count++;
                }
            });

            const avg = count > 0 ? parseFloat((total / count).toFixed(1)) : 0;

            data.push({
                name: param.name,
                areaName: area.name,
                score: avg,
                color: areaColor,
                fullMark: 11
            });
        });
    });

    return data;
  }, [currentBlockSessions, currentAreas, selectedSessionId]);

  // --- 2. Data Prep for MACRO Trend (History of Blocks) ---
  const macroTrendData = useMemo(() => {
    const dataPoints: any[] = [];

    const processBlock = (blockLabel: string, sessions: SessionData[], areasSnapshot: Area[]) => {
        const point: any = { name: blockLabel };

        areasSnapshot.forEach(area => {
            let areaSum = 0;
            let areaCount = 0;
            const paramIds = new Set(area.parameters.map(p => p.id));

            // Parameter specifics calculators
            const paramSums: Record<string, number> = {};
            const paramCounts: Record<string, number> = {};

            sessions.forEach(s => {
                Object.entries(s.scores).forEach(([pId, val]) => {
                    if (paramIds.has(pId)) {
                        areaSum += val as number;
                        areaCount++;

                        if(!paramSums[pId]) { paramSums[pId] = 0; paramCounts[pId] = 0; }
                        paramSums[pId] += val as number;
                        paramCounts[pId]++;
                    }
                });
            });

            point[area.name] = areaCount > 0 ? parseFloat((areaSum / areaCount).toFixed(1)) : 0;
            point[`${area.name}_id`] = area.id;

            area.parameters.forEach(p => {
                const pAvg = paramCounts[p.id] ? parseFloat((paramSums[p.id] / paramCounts[p.id]).toFixed(1)) : 0;
                point[`${p.name}`] = pAvg;
            });
        });

        if (Object.keys(point).length > 1) dataPoints.push(point);
    };

    history.forEach((block, idx) => {
        processBlock(`Blocco ${idx + 1}`, block.sessions, block.areaSnapshot);
    });

    // Add current block as the last point in Macro view
    const hasCurrentData = currentBlockSessions.some(s => Object.keys(s.scores).length > 0);
    if (hasCurrentData) {
        processBlock('Attuale', currentBlockSessions, currentAreas);
    }

    return dataPoints;
  }, [history, currentBlockSessions, currentAreas]);

  // --- 3. Data Prep for MICRO Trend (Sessions within current block) ---
  const microTrendData = useMemo(() => {
    return currentBlockSessions.map((session, i) => {
        // Use shorter label for X-Axis
        const point: any = { name: `S${i + 1}` };

        currentAreas.forEach(area => {
            let areaSum = 0;
            let areaCount = 0;

            area.parameters.forEach(p => {
                const val = session.scores[p.id];
                // Add individual parameter score to data point
                point[p.name] = val !== undefined ? val : null;

                if (val !== undefined) {
                    areaSum += val;
                    areaCount++;
                }
            });

            // Add Area Average to data point
            point[area.name] = areaCount > 0 ? parseFloat((areaSum / areaCount).toFixed(1)) : null;
        });

        return point;
    });
  }, [currentBlockSessions, currentAreas]);

  // --- 4. Trend Stats Cards Calculation ---
  const trends = useMemo(() => {
    const currentAverages: Record<string, {sum: number, count: number, color: string}> = {};
    chartData.forEach(d => {
        if(!currentAverages[d.areaName]) currentAverages[d.areaName] = {sum:0, count:0, color: d.color};
        currentAverages[d.areaName].sum += d.score;
        currentAverages[d.areaName].count++;
    });

    const lastBlock = history.length > 0 ? history[history.length - 1] : null;
    const trendsList: any[] = [];

    currentAreas.forEach(area => {
        const currObj = currentAverages[area.name];
        const current = currObj && currObj.count > 0 ? parseFloat((currObj.sum / currObj.count).toFixed(1)) : 0;

        let previous = 0;
        if (lastBlock) {
             let sum = 0, count = 0;
             const paramIds = new Set(area.parameters.map(p => p.id));
             lastBlock.sessions.forEach(s => {
                 Object.entries(s.scores).forEach(([pid, v]) => {
                     if (paramIds.has(pid)) { sum += (v as number); count++; }
                 });
             });
             previous = count > 0 ? parseFloat((sum/count).toFixed(1)) : 0;
        }

        const diff = current - previous;
        trendsList.push({
            id: area.id,
            name: area.name,
            current,
            previous,
            diff,
            isImproving: diff > 0,
            isStable: diff === 0,
            color: currObj ? currObj.color : '#64748b'
        });
    });
    return trendsList;
  }, [chartData, history, currentAreas]);

  // --- 5. Determine Lines to Show ---
  const linesToShow = useMemo(() => {
      if (!selectedHistoryArea) {
          // Show Area Averages
          return currentAreas.map((area, index) => ({
              key: area.name,
              color: getAreaColor(index),
              strokeWidth: 3,
              strokeDasharray: "0"
          }));
      } else {
          // Show Parameters for selected Area
          const area = currentAreas.find(a => a.name === selectedHistoryArea);
          if (!area) return [];
          const areaIndex = currentAreas.indexOf(area);
          const baseColor = getAreaColor(areaIndex);

          return area.parameters.map((p, idx) => ({
              key: p.name,
              color: baseColor, 
              strokeWidth: 2,
              strokeDasharray: idx % 2 === 0 ? "0" : "5 5" // Visual differentiation
          }));
      }
  }, [selectedHistoryArea, currentAreas]);

  return (
    <div className="flex flex-col h-full bg-slate-950 overflow-y-auto p-4 sm:p-6 space-y-8">

      {/* HEADER & CONTROLS */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-slate-800 pb-6">
        <div>
            <h2 className="text-2xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-300 to-blue-400 flex items-center gap-3 drop-shadow-sm">
            <Activity className="text-cyan-400" /> 
            Dashboard Coach
            </h2>
            <p className="text-slate-400 text-sm font-medium">Analisi performance e macro-cicli</p>
        </div>

        {/* SESSION SELECTOR */}
        <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                <Filter size={16} />
            </div>
            <select 
                value={selectedSessionId}
                onChange={(e) => setSelectedSessionId(e.target.value)}
                className="bg-slate-900 border border-slate-700 text-white text-sm rounded-lg focus:ring-cyan-500 focus:border-cyan-500 focus:shadow-[0_0_10px_rgba(6,182,212,0.3)] block w-full pl-10 p-2.5 appearance-none pr-10 outline-none hover:bg-slate-800 transition-colors cursor-pointer"
            >
                <option value="all">Media Intero Blocco</option>
                <option disabled>───────</option>
                {currentBlockSessions.map((s, idx) => (
                    <option key={s.id} value={s.id}>
                        {s.label} ({s.date ? new Date(s.date).toLocaleDateString('it-IT') : 'No data'})
                    </option>
                ))}
            </select>
            <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none text-slate-400">
                <ChevronDown size={16} />
            </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* BAR CHART: DETAILED PARAMETERS */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-xl lg:col-span-2 relative overflow-hidden">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                    <BarChart3 size={20} className="text-cyan-400 drop-shadow-[0_0_5px_rgba(34,211,238,0.5)]" /> 
                    {selectedSessionId === 'all' ? 'Dettaglio Parametri (Media Blocco)' : 'Dettaglio Parametri Sessione'}
                </h3>
            </div>

            <div className="h-[350px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 40 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis 
                            dataKey="name" 
                            stroke="#94a3b8" 
                            tick={{ fontSize: 10, fill: '#94a3b8' }} 
                            interval={0}
                            angle={-45}
                            textAnchor="end"
                        />
                        <YAxis 
                            domain={[0, 11]} 
                            stroke="#94a3b8" 
                            tick={{ fontSize: 12, fill: '#94a3b8' }}
                            tickCount={12}
                        />
                        <Tooltip 
                            cursor={{fill: '#1e293b', opacity: 0.4}}
                            contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', color: '#f8fafc', borderRadius: '8px' }}
                            itemStyle={{ color: '#fff' }}
                            formatter={(value: number) => [value, 'Punteggio']}
                        />
                        <Bar dataKey="score" name="Valore" radius={[4, 4, 0, 0]}>
                            {chartData.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={entry.color} />
                            ))}
                        </Bar>
                    </BarChart>
                </ResponsiveContainer>
            </div>
        </div>
      </div>

      {/* TREND ANALYSIS SECTION */}
      <div>
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4 mb-6">
            <div>
                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                    <TrendingUp size={20} className="text-fuchsia-400 drop-shadow-[0_0_5px_rgba(232,121,249,0.5)]" /> Analisi Andamento
                </h3>
                <p className="text-slate-400 text-sm mt-1">
                    Seleziona una tessera per filtrare e la vista temporale per il dettaglio.
                </p>
            </div>

            {/* TIME VIEW TOGGLE */}
            <div className="bg-slate-900 p-1 rounded-lg border border-slate-700 flex gap-1">
                <button
                    onClick={() => setTrendViewMode('micro')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        trendViewMode === 'micro' 
                        ? 'bg-fuchsia-600 text-white shadow-[0_0_10px_rgba(192,38,211,0.5)]' 
                        : 'text-slate-400 hover:text-white hover:bg-slate-800'
                    }`}
                >
                    <PlayCircle size={14} /> Sessioni Attuali (5)
                </button>
                <button
                    onClick={() => setTrendViewMode('macro')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        trendViewMode === 'macro' 
                        ? 'bg-fuchsia-600 text-white shadow-[0_0_10px_rgba(192,38,211,0.5)]' 
                        : 'text-slate-400 hover:text-white hover:bg-slate-800'
                    }`}
                >
                    <History size={14} /> Storico Blocchi
                </button>
            </div>
        </div>

        {/* TREND CARDS GRID */}
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 mb-6">
            <button
                onClick={() => setSelectedHistoryArea(null)}
                className={`p-3 rounded-xl border transition-all text-left ${
                    selectedHistoryArea === null 
                    ? 'bg-slate-800 border-fuchsia-500/50 shadow-[0_0_10px_rgba(192,38,211,0.2)]' 
                    : 'bg-slate-900 border-slate-800 hover:bg-slate-800'
                }`}
            >
                <span className="text-xs text-slate-400 font-bold uppercase block mb-1">Generale</span>
                <span className="text-sm text-white">Medie Aree</span>
            </button>

            {trends.map(t => (
                <button 
                    key={t.id}
                    onClick={() => setSelectedHistoryArea(selectedHistoryArea === t.name ? null : t.name)}
                    className={`p-3 rounded-xl border transition-all text-left relative overflow-hidden ${
                        selectedHistoryArea === t.name
                        ? 'bg-slate-800 ring-1 ring-cyan-500 shadow-[0_0_15px_rgba(6,182,212,0.2)]' 
                        : 'bg-slate-900 border-slate-800 hover:bg-slate-800'
                    }`}
                    style={{ borderColor: selectedHistoryArea === t.name ? t.color : '#1e293b' }}
                >   
                    <div className="absolute top-0 right-0 w-8 h-8 opacity-10 rounded-bl-full" style={{background: t.color}}></div>

                    <div className="flex justify-between items-start mb-2">
                        <span className="text-xs font-bold uppercase truncate pr-2" style={{ color: t.color }}>{t.name}</span>
                        {history.length > 0 && (
                            t.isStable ? <Minus size={14} className="text-slate-500" /> :
                            t.isImproving 
                            ? <TrendingUp size={14} className="text-emerald-400 drop-shadow-[0_0_5px_rgba(52,211,153,0.5)]" /> 
                            : <TrendingDown size={14} className="text-red-400 drop-shadow-[0_0_5px_rgba(248,113,113,0.5)]" />
                        )}
                    </div>
                    <div className="flex items-end gap-2">
                        <span className="text-xl font-bold text-white">
                            {t.current}
                        </span>
                    </div>
                </button>
            ))}
        </div>

        {/* DYNAMIC CHART (Micro vs Macro) */}
        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-xl relative">
             {/* Chart Title Overlay */}
            <div className="absolute top-4 right-6 text-xs font-mono text-cyan-500/50 font-bold pointer-events-none tracking-widest">
                {trendViewMode === 'micro' ? 'ANALISI MICRO-CICLO (Sessioni 1-5)' : 'ANALISI MACRO-CICLO (Storico)'}
            </div>

            <div className="h-[400px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <LineChart 
                        data={trendViewMode === 'micro' ? microTrendData : macroTrendData} 
                        margin={{ top: 20, right: 30, left: 10, bottom: 5 }}
                    >
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                        <XAxis dataKey="name" stroke="#94a3b8" tick={{fontSize: 12}} />
                        <YAxis domain={[0, 11]} stroke="#94a3b8" />
                        <Tooltip 
                             contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', color: '#f8fafc', borderRadius: '8px' }}
                        />
                        <Legend wrapperStyle={{ paddingTop: '10px' }}/>

                        {linesToShow.map((line) => (
                            <Line 
                                key={line.key}
                                type="monotone" 
                                dataKey={line.key} 
                                stroke={line.color} 
                                strokeWidth={line.strokeWidth}
                                strokeDasharray={line.strokeDasharray}
                                dot={{ fill: '#0f172a', strokeWidth: 2, r: 4 }}
                                activeDot={{ r: 6, strokeWidth: 0, fill: line.color }}
                                animationDuration={500}
                                connectNulls
                            />
                        ))}
                    </LineChart>
                </ResponsiveContainer>
            </div>

            <div className="flex justify-center mt-4 gap-4 text-xs text-slate-500">
                <div className="flex items-center gap-2">
                    <ZoomIn size={14} className="text-cyan-500" />
                    <span>
