import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route, useParams, Link, useNavigate } from 'react-router-dom';
import { Area, SessionData, TrainingBlock, DEFAULT_AREAS } from './types';
import { AthleteView } from './components/AthleteView';
import { SetupParameters } from './components/SetupParameters';
import { CoachDashboard } from './components/CoachDashboard';
import { Settings, User, LayoutDashboard, ArrowRight, Search, Menu, Lock, Key, LogIn, ShieldCheck } from 'lucide-react';
import { Button } from './components/Button';

// --- DATA LOGIC & UTILS ---

const randomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

// Generate random data specifically for a given ID if empty (Simulates fetching existing cloud data)
const generateRandomBlock = (areas: Area[]): SessionData[] => {
  const now = new Date();
  return Array.from({ length: 5 }, (_, i) => {
    const scores: Record<string, number> = {};
    areas.forEach(area => {
        area.parameters.forEach(param => {
            scores[param.id] = randomInt(4, 10);
        });
    });
    const sessionDate = new Date(now);
    sessionDate.setDate(now.getDate() - (4 - i));

    return {
      id: `session-${Date.now()}-${i}`,
      label: `Sessione ${i + 1}`,
      date: sessionDate.toISOString().split('T')[0],
      rpe: randomInt(5, 9),
      scores: scores,
      notes: `Sessione generata per test. Sensazioni variabili.`,
      completed: true
    };
  });
};

const generateEmptyBlock = (): SessionData[] => {
  return Array.from({ length: 5 }, (_, i) => ({
    id: `session-${Date.now()}-${i}`,
    label: `Sessione ${i + 1}`,
    date: '',
    rpe: 0,
    scores: {},
    notes: '',
    completed: false
  }));
};

const downloadJSON = (data: any, filename: string) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
};

// --- HOOK: ATHLETE SIDE (Cloud Writer) ---
const useAthleteLogic = (athleteId: string) => {
  const cloudKey = `flux_${athleteId}_cloud_inbox`;
  const areasKey = `flux_${athleteId}_areas`;
  const draftKey = `flux_${athleteId}_draft_block`;

  const [areas, setAreas] = useState<Area[]>(() => {
    const saved = localStorage.getItem(areasKey);
    return saved ? JSON.parse(saved) : DEFAULT_AREAS;
  });

  const [currentSessions, setCurrentSessions] = useState<SessionData[]>(() => {
    const saved = localStorage.getItem(draftKey);
    return saved ? JSON.parse(saved) : generateEmptyBlock();
  });

  useEffect(() => { localStorage.setItem(areasKey, JSON.stringify(areas)); }, [areas, athleteId]);
  useEffect(() => { localStorage.setItem(draftKey, JSON.stringify(currentSessions)); }, [currentSessions, athleteId]);

  const handleSubmitBlock = (finalSessions: SessionData[]) => {
    const newBlock: TrainingBlock = {
        id: `block-${Date.now()}`,
        submittedAt: new Date().toISOString(),
        areaSnapshot: JSON.parse(JSON.stringify(areas)),
        sessions: finalSessions
    };

    const existingCloudStr = localStorage.getItem(cloudKey);
    const existingCloud = existingCloudStr ? JSON.parse(existingCloudStr) : [];

    const updatedCloud = [...existingCloud, newBlock];
    localStorage.setItem(cloudKey, JSON.stringify(updatedCloud));

    setCurrentSessions(generateEmptyBlock());

    alert("Dati inviati al Cloud! In attesa di sincronizzazione del Coach.");
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return { areas, setAreas, currentSessions, setCurrentSessions, handleSubmitBlock };
};

// --- HOOK: COACH SIDE (Local Archive Reader & Sync Manager) ---
const useCoachLogic = (athleteId: string) => {
  const cloudKey = `flux_${athleteId}_cloud_inbox`;
  const archiveKey = `flux_${athleteId}_local_archive`;
  const areasKey = `flux_${athleteId}_areas`;

  const [localHistory, setLocalHistory] = useState<TrainingBlock[]>(() => {
    const saved = localStorage.getItem(archiveKey);
    return saved ? JSON.parse(saved) : [];
  });

  const [currentAreas, setCurrentAreas] = useState<Area[]>(() => {
      const saved = localStorage.getItem(areasKey);
      return saved ? JSON.parse(saved) : DEFAULT_AREAS;
  });

  const [pendingCount, setPendingCount] = useState(0);

  const checkForUpdates = useCallback(() => {
    const cloudDataStr = localStorage.getItem(cloudKey);
    const cloudData = cloudDataStr ? JSON.parse(cloudDataStr) : [];
    setPendingCount(cloudData.length);

    const savedAreas = localStorage.getItem(areasKey);
    if (savedAreas) setCurrentAreas(JSON.parse(savedAreas));

  }, [cloudKey, areasKey]);

  useEffect(() => {
      checkForUpdates();
      const interval = setInterval(checkForUpdates, 3000); 
      return () => clearInterval(interval);
  }, [checkForUpdates]);

  const syncAndDownload = () => {
    const cloudDataStr = localStorage.getItem(cloudKey);
    if (!cloudDataStr) return;

    const newBlocks: TrainingBlock[] = JSON.parse(cloudDataStr);
    if (newBlocks.length === 0) return;

    const updatedLocal = [...localHistory, ...newBlocks];
    setLocalHistory(updatedLocal);
    localStorage.setItem(archiveKey, JSON.stringify(updatedLocal));

    const filename = `FLUX_${athleteId}_BACKUP_${new Date().toISOString().slice(0,10)}.json`;
    downloadJSON(newBlocks, filename);

    localStorage.removeItem(cloudKey);
    setPendingCount(0);

    alert(`Sincronizzazione Completata!\n\n- ${newBlocks.length} Blocchi scaricati e salvati in locale.\n- Backup JSON generato.\n- Dati Cloud ELIMINATI per sicurezza.`);
  };

  return { localHistory, currentAreas, pendingCount, syncAndDownload };
};

