                                </div>
                            </div>
                            <ArrowRight className="text-slate-600 group-hover:text-fuchsia-400 transform group-hover:translate-x-1 transition-all" />
                        </div>
                    </Link>
                </div>

                <div className="mt-12">
                   <AuthorSignature />
                </div>
            </div>
        </div>
    );
};

