import React, { useState, useEffect } from 'react';
import { Area, SessionData, getAreaColor } from '../types';
import { Button } from './Button';
import { Save, Send, AlertCircle, Calendar, CheckCircle2 } from 'lucide-react';

interface AthleteViewProps {
  areas: Area[];
  sessions: SessionData[];
  onSaveSessions: (sessions: SessionData[]) => void;
  onSubmitBlock: (sessions: SessionData[]) => void;
}

export const AthleteView: React.FC<AthleteViewProps> = ({ 
  areas, 
  sessions, 
  onSaveSessions, 
  onSubmitBlock 
}) => {
  const [activeSessionId, setActiveSessionId] = useState<string>(sessions[0].id);
  const [localSessions, setLocalSessions] = useState<SessionData[]>(sessions);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [showSuccess, setShowSuccess] = useState(false);

  // Sync local state when props change (external updates or reset)
  useEffect(() => {
    setLocalSessions(sessions);

    // Logic to handle "Infinite Cycle":
    // If the currently active ID no longer exists (because we reset the block),
    // automatically jump back to the first session of the new block and show success.
    const currentIdExists = sessions.some(s => s.id === activeSessionId);
    if (!currentIdExists && sessions.length > 0) {
        setActiveSessionId(sessions[0].id);
        setShowSuccess(true);
        // Hide success message after 3 seconds
        const timer = setTimeout(() => setShowSuccess(false), 3000);
        return () => clearTimeout(timer);
    }
  }, [sessions, activeSessionId]);

  const activeSession = localSessions.find(s => s.id === activeSessionId) || localSessions[0];

  const updateSession = (updater: (s: SessionData) => SessionData) => {
    const updated = localSessions.map(s => 
      s.id === activeSessionId ? updater(s) : s
    );
    setLocalSessions(updated);
  };

  const handleScoreChange = (paramId: string, value: number) => {
    updateSession(s => ({
      ...s,
      scores: { ...s.scores, [paramId]: value }
    }));
  };

  const handleRpeChange = (value: number) => {
    updateSession(s => ({ ...s, rpe: value }));
  };

  const handleNotesChange = (text: string) => {
    updateSession(s => ({ ...s, notes: text }));
  };

  const handleManualSave = () => {
    onSaveSessions(localSessions);
    setLastSaved(new Date());
  };

  const handleSubmit = () => {
    if (confirm("Sei sicuro di voler inviare questo blocco di 5 sessioni? I dati verranno archiviati e potrai iniziare un nuovo ciclo.")) {
        onSubmitBlock(localSessions);
    }
  };

  // Logic for Performance Color (Red -> Green) mapped to 1-11
  const getPerformanceColorClass = (val: number) => {
    if (val <= 2) return 'bg-red-600 shadow-[0_0_10px_rgba(220,38,38,0.5)] text-white';
    if (val <= 4) return 'bg-orange-500 shadow-[0_0_10px_rgba(249,115,22,0.5)] text-white';
    if (val <= 6) return 'bg-yellow-400 shadow-[0_0_10px_rgba(250,204,21,0.5)] text-slate-900';
    if (val <= 8) return 'bg-lime-400 shadow-[0_0_10px_rgba(163,230,53,0.5)] text-slate-900';
    return 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)] text-white';
  };

  // Logic for RPE text color (Intensity)
  const getRpeColor = (val: number) => {
    if (val < 4) return 'text-cyan-400 drop-shadow-[0_0_5px_rgba(34,211,238,0.6)]';
    if (val < 7) return 'text-yellow-400 drop-shadow-[0_0_5px_rgba(250,204,21,0.6)]';
    if (val < 9) return 'text-orange-400 drop-shadow-[0_0_5px_rgba(251,146,60,0.6)]';
    return 'text-red-500 drop-shadow-[0_0_5px_rgba(239,68,68,0.6)]';
  };

  // Specific labels for the 1-11 scale
  const getScaleLabel = (val: number) => {
    switch(val) {
      case 1: return "Molto molto poco";
      case 2: return "Molto poco";
      case 3: return "Moderatamente";
      case 5: return "Molto";
      case 7: return "Moltissimo";
      case 10: return "Estremamente elevato";
      case 11: return "Max pox";
      default: return "";
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 relative">

      {/* SUCCESS OVERLAY */}
      {showSuccess && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/90 backdrop-blur-lg animate-in fade-in duration-300">
              <div className="text-center p-8 bg-slate-900 border border-emerald-500/50 rounded-2xl shadow-[0_0_50px_rgba(16,185,129,0.3)] max-w-sm mx-4 transform animate-bounce-in">
                  <div className="w-20 h-20 bg-emerald-500/20 rounded-full flex items-center justify-center mx-auto mb-6 shadow-[0_0_20px_rgba(16,185,129,0.5)]">
                      <CheckCircle2 size={40} className="text-emerald-400" />
                  </div>
                  <h3 className="text-2xl font-black text-white mb-2">Blocco Inviato!</h3>
                  <p className="text-emerald-200/80 mb-6">
                      I dati sono stati salvati correttamente. Il tuo diario è stato resettato ed è pronto per il prossimo ciclo di 5 allenamenti.
                  </p>
                  <Button onClick={() => setShowSuccess(false)} className="w-full bg-emerald-600 hover:bg-emerald-500 text-white shadow-[0_0_15px_rgba(16,185,129,0.4)] border-none">
                      Inizia Nuovo Blocco
                  </Button>
              </div>
          </div>
      )}

      {/* Header / Nav */}
      <div className="bg-slate-900/80 backdrop-blur border-b border-slate-800 p-4 sticky top-0 z-20">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
            <div>
                 <h2 className="text-xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-300 to-blue-400 drop-shadow-sm tracking-tight">Diario Allenamento</h2>
                 <p className="text-xs text-slate-400 font-mono mt-0.5">
                     {lastSaved ? `Salvataggio: ${lastSaved.toLocaleTimeString()}` : 'Modifiche non salvate'}
                 </p>
            </div>
            <div className="flex gap-2">
                <Button variant="secondary" size="sm" onClick={handleManualSave} className="gap-2 border-slate-700 hover:border-cyan-500/50 hover:text-cyan-300">
                    <Save size={16} /> Salva Bozza
                </Button>
                <Button variant="primary" size="sm" onClick={handleSubmit} className="gap-2 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 shadow-[0_0_15px_rgba(8,145,178,0.4)] border-none">
                    <Send size={16} /> Invia Blocco
                </Button>
            </div>
        </div>

        {/* Session Tabs */}
        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
            {localSessions.map((s, idx) => (
                <button
                    key={s.id}
                    onClick={() => setActiveSessionId(s.id)}
                    className={`flex flex-col items-center min-w-[4.5rem] p-2 rounded-lg border transition-all ${
                        activeSessionId === s.id 
                        ? 'bg-cyan-950/40 border-cyan-500 text-cyan-300 shadow-[0_0_10px_rgba(6,182,212,0.2)]' 
                        : 'bg-slate-900 border-slate-800 text-slate-500 hover:bg-slate-800 hover:text-slate-300'
                    }`}
                >
                    <span className="text-xs font-black uppercase tracking-wider">Sess {idx + 1}</span>
                    <span className="text-[10px] opacity-70 truncate w-full text-center">
                        {s.date ? new Date(s.date).toLocaleDateString('it-IT', {weekday:'short'}) : '-'}
                    </span>
                </button>
            ))}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 max-w-3xl mx-auto w-full space-y-8">

        {/* Date Selector */}
        <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800 hover:border-slate-700 transition-colors">
            <label className="text-cyan-400 text-xs font-bold uppercase mb-2 block flex items-center gap-2 tracking-wider">
                <Calendar size={14} className="text-cyan-400" /> Data Sessione
            </label>
            <input 
                type="date" 
                value={activeSession.date}
                onChange={(e) => updateSession(s => ({ ...s, date: e.target.value }))}
                className="bg-slate-950 border border-slate-700 rounded-lg px-4 py-2 text-white w-full sm:w-auto focus:border-cyan-500 focus:shadow-[0_0_10px_rgba(6,182,212,0.2)] outline-none transition-all"
            />
        </div>

        {/* RPE Scale */}
        <div className="bg-slate-900 rounded-xl border border-slate-800 p-6 shadow-xl relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-cyan-400 to-blue-600 shadow-[0_0_10px_rgba(34,211,238,0.5)]"></div>
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white group-hover:text-cyan-100 transition-colors">RPE <span className="text-xs font-normal text-slate-500 uppercase tracking-wide ml-2">Sforzo Percepito</span></h3>
                <span className={`text-3xl font-black ${getRpeColor(activeSession.rpe)}`}>
                    {activeSession.rpe} <span className="text-sm text-slate-500 font-normal opacity-50">/ 11</span>
                </span>
            </div>

            <input
                type="range"
                min="0"
                max="11"
                step="0.5"
                value={activeSession.rpe}
                onChange={(e) => handleRpeChange(parseFloat(e.target.value))}
                className="w-full h-3 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-400 hover:accent-cyan-300 transition-all"
            />
            <div className="flex justify-between text-xs text-slate-500 mt-2 font-mono uppercase tracking-wide">
                <span>Riposo</span>
                <span className="text-cyan-500/50">Moderato</span>
                <span className="text-red-500/50">Massimale</span>
            </div>
        </div>

        {/* Notes */}
        <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800 hover:border-slate-700 transition-colors">
            <label className="text-slate-400 text-xs font-bold uppercase mb-2 block tracking-wider">Note & Sensazioni</label>
            <textarea
                value={activeSession.notes}
                onChange={(e) => handleNotesChange(e.target.value)}
                placeholder="Come ti sei sentito? Dettagli tecnici o fisici..."
                className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-white focus:border-cyan-500 focus:shadow-[0_0_10px_rgba(6,182,212,0.2)] outline-none transition-all min-h-[100px]"
            />
        </div>

        {/* Dynamic Parameters */}
        <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-200 flex items-center gap-2 uppercase tracking-widest text-xs opacity-70">
                Metriche Valutazione
            </h3>

            {areas.length === 0 && (
                <div className="text-center p-8 border border-dashed border-slate-800 rounded-lg text-slate-500">
                    <AlertCircle className="mx-auto mb-2" />
