                <div 
                    key={area.id} 
                    className="bg-slate-900/50 rounded-xl border border-slate-800/60 p-5 relative overflow-hidden transition-all hover:border-slate-700 hover:shadow-[0_0_15px_rgba(0,0,0,0.3)]"
