                rpe: randomInt(3, 9),
                scores: scores,
                notes: `Allenamento mock ${b+1}-${s+1}`,
                completed: true
            });
        }

        blocks.push({
            id: `mock-block-${b}`,
            submittedAt: submitDate.toISOString(),
            areaSnapshot: JSON.parse(JSON.stringify(areas)), // Deep copy
