        }

        blocks.push({
            id: `mock-block-${b}`,
            submittedAt: submitDate.toISOString(),
            areaSnapshot: JSON.parse(JSON.stringify(areas)), // Deep copy
            sessions: sessions
        });
    }
    return blocks;
};

