// --- HOOK: ATHLETE SIDE (Cloud Writer) ---
const useAthleteLogic = (athleteId: string) => {
  const cloudKey = `flux_${athleteId}_cloud_inbox`;
  const areasKey = `flux_${athleteId}_areas`;
  const draftKey = `flux_${athleteId}_draft_block`;

  const [areas, setAreas] = useState<Area[]>(() => {
    const saved = localStorage.getItem(areasKey);
    return saved ? JSON.parse(saved) : DEFAULT_AREAS;
  });

  // Re-read areas if localStorage changes (sync mechanism)
  useEffect(() => {
    const handleStorageChange = () => {
        const saved = localStorage.getItem(areasKey);
        if (saved) setAreas(JSON.parse(saved));
    };
    window.addEventListener('storage', handleStorageChange);
    // Poll for changes too since we are in same browser session simulation
    const interval = setInterval(() => {
        const saved = localStorage.getItem(areasKey);
        if(saved && saved !== JSON.stringify(areas)) {
             setAreas(JSON.parse(saved));
        }
    }, 1000);

    return () => {
        window.removeEventListener('storage', handleStorageChange);
        clearInterval(interval);
    };
  }, [areasKey, areas]);

  const [currentSessions, setCurrentSessions] = useState<SessionData[]>(() => {
    const saved = localStorage.getItem(draftKey);
    return saved ? JSON.parse(saved) : generateEmptyBlock();
  });

  useEffect(() => { localStorage.setItem(areasKey, JSON.stringify(areas)); }, [areas, athleteId]);
  useEffect(() => { localStorage.setItem(draftKey, JSON.stringify(currentSessions)); }, [currentSessions, athleteId]);

  const handleSubmitBlock = (finalSessions: SessionData[]) => {
    const newBlock: TrainingBlock = {
        id: `block-${Date.now()}`,
        submittedAt: new Date().toISOString(),
        areaSnapshot: JSON.parse(JSON.stringify(areas)),
        sessions: finalSessions
    };

    const existingCloudStr = localStorage.getItem(cloudKey);
    const existingCloud = existingCloudStr ? JSON.parse(existingCloudStr) : [];

    const updatedCloud = [...existingCloud, newBlock];
    localStorage.setItem(cloudKey, JSON.stringify(updatedCloud));

    setCurrentSessions(generateEmptyBlock());

    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return { areas, setAreas, currentSessions, setCurrentSessions, handleSubmitBlock };
};

// --- HOOK: COACH REGISTRY & LOGIC ---
const useCoachRegistry = () => {
    const registryKey = 'flux_coach_registry';
    const [athletes, setAthletes] = useState<AthleteProfile[]>([]);

    useEffect(() => {
        const load = () => {
            const saved = localStorage.getItem(registryKey);
            if (saved) setAthletes(JSON.parse(saved));
        };
        load();
        const interval = setInterval(load, 2000); // Poll for new athletes
        return () => clearInterval(interval);
    }, []);

    const addAthlete = (fullName: string, sport: string, email: string, phone: string) => {
        const cleanName = fullName.trim();
        if (!cleanName) return;

        // Generate ID: name-surname-random
        const slug = cleanName.toLowerCase().replace(/[^a-z0-9]+/g, '-');
        const uniqueSuffix = Math.random().toString(36).substring(2, 6);
        const newId = `${slug}-${uniqueSuffix}`;

        const newAthlete: AthleteProfile = {
            id: newId,
            name: cleanName,
            sport: sport.trim() || 'Generale',
            email: email.trim(),
            phone: phone.trim(),
            createdAt: new Date().toISOString()
        };

        const updated = [...athletes, newAthlete];
        setAthletes(updated);
        localStorage.setItem(registryKey, JSON.stringify(updated));
    };

    const removeAthlete = (id: string) => {
        if(confirm("Sei sicuro? Questo rimuoverà l'atleta dalla lista, ma non cancellerà i suoi dati storici salvati.")){
            const updated = athletes.filter(a => a.id !== id);
            setAthletes(updated);
            localStorage.setItem(registryKey, JSON.stringify(updated));
        }
    };

    return { athletes, addAthlete, removeAthlete };
};

// --- HOOK: COACH DATA LOGIC (Single Athlete) ---
const useCoachDataLogic = (athleteId: string) => {
  const cloudKey = `flux_${athleteId}_cloud_inbox`;
  const archiveKey = `flux_${athleteId}_local_archive`;
  const areasKey = `flux_${athleteId}_areas`;

  const [localHistory, setLocalHistory] = useState<TrainingBlock[]>([]);
  const [currentAreas, setCurrentAreas] = useState<Area[]>(DEFAULT_AREAS);
  const [pendingCount, setPendingCount] = useState(0);

  // Load data whenever athleteId changes
  useEffect(() => {
      if (!athleteId) return;

      const loadData = () => {
          const savedHistory = localStorage.getItem(archiveKey);
          setLocalHistory(savedHistory ? JSON.parse(savedHistory) : []);

          const savedAreas = localStorage.getItem(areasKey);
          setCurrentAreas(savedAreas ? JSON.parse(savedAreas) : DEFAULT_AREAS);

          const cloudDataStr = localStorage.getItem(cloudKey);
          const cloudData = cloudDataStr ? JSON.parse(cloudDataStr) : [];
          setPendingCount(cloudData.length);
      };

      loadData();

      // Setup listener/poller for sync
      const interval = setInterval(loadData, 2000); 
      return () => clearInterval(interval);

  }, [athleteId, archiveKey, areasKey, cloudKey]);


  const syncAndDownload = () => {
    const cloudDataStr = localStorage.getItem(cloudKey);
    if (!cloudDataStr) return;

    const newBlocks: TrainingBlock[] = JSON.parse(cloudDataStr);
    if (newBlocks.length === 0) return;

    const updatedLocal = [...localHistory, ...newBlocks];
    setLocalHistory(updatedLocal);
    localStorage.setItem(archiveKey, JSON.stringify(updatedLocal));

    const filename = `FLUX_${athleteId}_BACKUP_${new Date().toISOString().slice(0,10)}.json`;
    downloadJSON(newBlocks, filename);

    localStorage.removeItem(cloudKey);
    setPendingCount(0);

    alert(`Sincronizzazione Completata!\n\n- ${newBlocks.length} Blocchi scaricati.\n- Database locale aggiornato.\n- Backup JSON salvato.`);
  };

  const updateAreas = (newAreas: Area[]) => {
      setCurrentAreas(newAreas);
      localStorage.setItem(areasKey, JSON.stringify(newAreas));
  };

  return { localHistory, currentAreas, updateAreas, pendingCount, syncAndDownload };
};

