    <button onClick={onClick} disabled={disabled} style={{ padding: '8px 16px', margin: '4px', borderRadius: '4px', border: '1px solid #ccc', backgroundColor: disabled ? '#eee' : '#fff', cursor: disabled ? 'default' : 'pointer' }}>
