    setLocalAreas(localAreas.filter(a => a.id !== id));
  };

  const updateAreaName = (id: string, name: string) => {
    setLocalAreas(localAreas.map(a => a.id === id ? { ...a, name } : a));
    setEditingId(null);
  };

